(window.STORIES=window.STORIES||[]).push(...[{"n": 139, "l": "الجزء 113 | أحداث السنه السادسه من الهجرة | مابعد الحديبية", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_عشر\n#أحداث_السنة_السادسة_من_الهجرة\n#ما_بعد_الحديبية\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما قام يذبح الهدي بتاعه ويحلق شعر رأسه عشان يتحلل من الإحرام،\nلكن قبل ما نكمل عايز أوضح نقطة\nالحديث إللي قلناه المرة إللي فاتت عن إصلاح ذات البين:\nألا أخبركم بأفضل من درجة الصيام والصدقة والصلاة، فقال أبو الدرداء : قلنا بلى يا رسول الله ، \nقال :إصلاح ذات البين\"\nالمقصود هنا بالصلاة والصدقة والصيام بالنوافل مش الفرائض، يعني رسول الله ﷺ بيقول إن إصلاح ذات البين أفضل من نوافل الصلاة والصدقة والصيام، \nلكن مش أفضل من فرائض الصلاة الخمس ولا أفضل من صيام شهر رمضان الفرض ولا هي أفضل من الزكاة مثلا،\nلأ، الأفضلية هنا بين النوافل فقط \nنرجع لرسول الله ﷺ وهو بيذبح الهدي، الصحابة لما شافوا رسول الله ﷺ قام يذبح الهدي بتاعه عرفوا خلاص إن كده مفيش أي أمل إنهم يدخلوا مكة يكملوا عمرتهم فقاموا كلهم وبدأوا يذبحوا الهدي بتاعهم ويحلقوا رؤوسهم،\nولكن قاموا وهم مغمومين لدرجة إنهم كادوا يقتلوا بعض من الغم،\nيعني مثلا لما الواحد بيكون بيقطع حاجة بالسكينة وهو متضايق وزعلان أو مغموم مش ساعات بيتعور\nلأن ساعتها مش بيبقى مركز هو بيعمل إيه لكن تركيزه كله في الهم والغم إللي هو فيه،\nكذلك الصحابة في الموقف ده كانوا مهمومين ومغمومين فكادوا يقتلوا بعض من الغم،\n☆طيب ليه الصحابة مسمعوش كلام رسول الله ﷺ من أول مرة قال لهم يقوموا يذبحوا الهدي مع إنهم زي ما قال عروة بن مسعود الثقفي في وصفهم إنهم مجرد ما رسول الله ﷺ كان يأمر أمر الكل بيسارع في تنفيذ الأمر ده\nالصحابة كان عندهم أمل إن الوحي ينزل ويقول لهم ادخلوا مكة وكملوا العمرة، يعني كانوا زي الغريق إللي بيتعلق بقشة زي ما بيقولوا\nفلما رسول الله ﷺ قال لهم يقوموا يتحللوا مكنوش مستوعبين، يعني هو بجد كده خلاص مفيش أي أمل إننا نكمل العمرة بعد ما جينا المشوار ده كله، \nطيب وأبو جندل هنسيبه فعلا لقريش يعذبوه ومش هننقذه وناخده معانا\nتقدروا تقولوا إنهم كانوا في حالة صدمة\nعشان كده رسول الله ﷺ كان عاذرهم وتعامل مع الموضوع بكل حكمة لما لقاهم مستجابوش لأمره تركهم لحد ما يلاقي حل، وهو كان حاسس باللي هم حاسين بيه وشايف الأزمة إللي هم فيها، \nلكن الفرق إن رسول الله ﷺ كان شايف المصالح إللي هتيجي من وراء المعاهدة دي وإللي الصحابة مكنوش شايفينها،\nوانتم عارفين الإنسان لما بيكون مهموم أو في ابتلاء مبيشفش قصاده،\nفلما خرج رسول الله ﷺ وبدأ هو يذبح الهدي عرفوا خلاص إن مفيش وحي هينزل يقول لهم يكملوا العمرة فهنا بقى قاموا كلهم وبدأوا ينفذوا أمر رسول الله ﷺ،\nوبكده انتهت مشكلة كبيرة جدا كانت هتحصل بين رسول الله ﷺ والصحابة بسبب رأي أم سلمة رضي الله عنها.\n☆وهنا في فائدة وهي إن رسول الله ﷺ شارك أم سلمة رضي الله عنها في همومه ومشاكله وكمان استشارها وأخذ برأيها مع إن الموضوع يعتبر ميخصهاش،\nومع ذلك رسول الله ﷺ لما هي سألته زعلان ليه، مقلهاش مثلا دي حاجة متخصكيش أو انتِ مش هتفهمي المشكلة دي أو...أو...\nحكى لها وسمع منها رأيها وكمان أخذ بيه، فمفيش مشكلة خالص إن الرجل يستشير زوجته في أمور تخصه حتى لو كانت هي خارج الموضوع وملهاش علاقة بيه،\nومحدش يقول بقى لما هي تبقى زي أم سلمة أبقى أستشيرها\nالشاهد من الموقف إن الأعلى منزلة والأعقل والأحكم وهو رسول الله ﷺ استشار إللي أقل منه، فالزوج مش زي رسول الله ﷺ ولا الزوجة زي أم سلمة لكن احنا بناخد العبرة من الموقف وهو عبرة استشارة الزوج  لزوجته،\nهي كان عندها رأي خَفِي على رسول الله ﷺ واحنا قلنا قبل كده إن رسول الله ﷺ ممكن يخفى عليه أمور ربنا يعلمها له عن طريق الاستشارة، سواء استشارة أصحابة أو استشارة أزواجه، \nوالحكمة من كده إن رسول الله ﷺ قدوة لنا كرجال ونساء في كل شيء فلازم تحصل معاه مواقف وهو يتصرف فيها بطريقة معينة عشان إللي ييجي بعده واتحط في نفس الموقف يتصرف زيه بالضبط،\nومن المواقف دي استشارته لزوجاته في أمور مهمة، أيوة في بعض أراء للنساء تودي في داهية\nلكن برده لهم آراء حكيمة في أوقات تانية، فالزوج هو إللي يحدد بقى ينفع يستشير زوجته ولّا لأ،\nيعني واحد زوجته بتتقي الله وعندها علم وليها نظرة ثاقبة، إيه المانع إن يستشيرها\nلكن للأسف في أزواج بيرفضوا آراء زوجاتهم مع إنها آراء صحيحة لمجرد فقط إنها امرأة بحجة إنها مبتفهمش حاجة أو متعرفش أو...أو..\nلكن دي بتكون نظرته لها للأسف، فأكيد إللي بالعقلية دي لا يتبع سنة رسول الله ﷺ في النقطة دي\nنرجع لرسول الله ﷺ ونشوفه عمل إيه\nرسول الله ﷺ حلق شعر رأسه فحلق بعض الصحابة زي رسول الله ﷺ  وبعض الصحابة لم يحلقوا ولكن قصروا من شعورهم، \nفلما رآهم رسول الله ﷺ قال:\nاللهم ارحم المُحَلّقين \nفالصحابة إللي قصروا قالوا : والمقصرين يا رسول الله \nيعني بيطلبوا منه إنه يدعو كمان للي بيقصروا شعرهم ومش بيحلقوه كله،\nفقال رسول الله ﷺ مرة ثانية:\nاللهم ارحم المحلقين \nفالصحابة قالوا: \nوالمقصرين يا رسول الله \nثلاث مرات يدعوا للمُحلقين، والصحابة يطلبوا منه الدعاء للمقصرين، ففي المرة الرابعة قال ﷺ: والمقصرين\n☆ملحوظة\nالحلق في العمرة أفضل لو كان وقت العمرة بعيد عن وقت الحج، يعني مثلا رجل اعتمر في رمضان وسيحج في نفس العام لما يتحلل من العمرة الأفضل إنه يحلق شعر رأسه، \nولما يحج يحلق شعر رأسه مرة ثانية لما يتحلل من إحرامه في الحج، \nلكن لو عمل عمرة في ذي القعدة مثلا وسيحج بعدها في ذي الحجة فالأفضل هنا إنه يُقصر شعره ويترك الحلق للحج،\nزي ما رسول الله ﷺ عمل كده، رسول الله ﷺ حلق شعره كامل لأنه مش هيحج\nبعد ما خلاص المسلمين ذبحوا وحلقوا جاء لرسول الله ﷺ  نساء مؤمنات من قريش،\nمن النساء دول أم كلثوم بنت عُقبة بن أبي مُعَيط إللي قُتل بعد غزوة بدر صَبْرا واتكلمنا عليه قبل كده،\nفلما جاءت لرسول الله ﷺ جاء وراها إخوتها الاثنين عمارة والوليد عشان يرجعوها،\nلأن المفروض على حسب العهد إللي بين رسول الله ﷺ والمشركين إن أي أحد يأتي مسلما من قريش لرسول الله ﷺ يجب على رسول الله ﷺ إنه يرجعه لقريش،\nلكن هل النساء تدخل في الشرط ده \nنزلت الآيات تفصّل في المسألة،\nأخرج القرآن النساء من المعاهدة دي ومنع المسلمين إنهم يردُّوا النساء إللي جاءوا مسلمات إلى المشركين لأنهن لا يَحلّون للمشركين،\n\"لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ\"\nلكن كده في مشكلة\nماهو ممكن أي واحدة كرهت زوجها ومش عايزة تعيش معاه تقول أنا أسلمت عشان تسيبه، أو مثلا واحدة كانت بتحب حد من الصحابة فتهاجر للمدينة وتقول انا أسلمت عشان تبقى جنبه\nفكان لازم الامتحان والاختبار، فكان رسول الله ﷺ يمتحن النساء ويسألهن بالله:\nانتِ خرجتي ليه، هل فعلا خرجتي عشان عايزة الله ورسوله ولّا هربانة من زوج أو مش عايزة تعيشي في البلد أو...أو....\nفلو قالت إنها فعلا خرجت لله ولرسوله ومش عايزة غير الإسلام يبقى لا يردوها للمشركين،\nلكن لو قالت إنها هربت أو قالت أي سبب تاني غير الإسلام يرجعوها تاني للمشركين،\n☆طيب ما هي ممكن تكذب \n◇أولا:\n احنا ملناش غير الظاهر ورسول الله ﷺ نفسه قال :\n\" إِنِّي لَمْ أُومَرْ أَنْ أَنْقُبَ عَنْ قُلُوبِ النَّاسِ ، وَلا أَشُقَّ بُطُونَهُمْ\"\nده غير إن في الوقت ده الناس كانت بتأنف الكذب، يعني كان معروف إن الكذب ده حاجة سيئة جدا فكانوا بيترفعوا عن الكذب حتى لو فيه مصلحة،\n◇ثانيا:\n القرآن كان بينزل ساعتها فكانوا عارفين إن إللي هيخبي حاجة ربنا هيظهرها وينزل القرآن يفضح إللي في القلوب\nفبعد الامتحان وخلاص عرفوا إن المرأة مؤمنة لا ترجع إلى المشركين، قال تعالى في سورة الممتحنة:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا جَاءَكُمُ الْمُؤْمِنَاتُ مُهَاجِرَاتٍ فَامْتَحِنُوهُنَّ اللَّهُ أَعْلَمُ بِإِيمَانِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَاتٍ فَلَا تَرْجِعُوهُنَّ إِلَى الْكُفَّارِ  \" \nونزل التحريم بزواج المؤمنين من المشركات أو الاستمرار في الزواج منهن، \n\"وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ\"\nفطلق عمر بن الخطاب رضي الله عنه زوجتين له كانتا على الشرك، ولا يجوز للمسلمين إنهم يتزوجوا من الوثنيين إللي بيعبدوا الأصنام،\nبعكس المُحصنات من أهل الكتاب ربنا أباح للمسلمين إنهم يتزوجوهن وطبعا بشروط معينة مش أي واحد يروح يتزوج أي واحدة كده من أهل الكتاب زي ما الناس فاهمة\nفلما حصل التفريق بين المشركين والمؤمنين ربنا أمر المؤمنين إنهم يطلبوا المهر إللي كانوا دفعوه للنساء المشركات لما تزوجوهن، \nوإن المسلمين يردوا للمشركين المهر إللي كانوا دفعوه للمسلمات لما تزوجوهن، يعني كل واحد يرجع مهر التاني سواء المشركات أو المؤمنات،\n\"وَاسْأَلُوا مَا أَنفَقْتُمْ وَلْيَسْأَلُوا مَا أَنفَقُوا\" \nخلاص كده المسلمون تحللوا وجمعوا حاجتهم وتركوا الحديبية وراجعين للمدينة، في الطريق نزلت سورة الفتح تعلق على صلح الحديبية،\n\"إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا \"\nأول ما نزلت السورة أرسل رسول الله ﷺ في طلب عمر، طبعا ساعتها عمر رضي الله عنه كان خايف إنه ينزل فيه قرآن بسبب إللي عمله مع رسول الله ﷺ،\nفجاء لرسول الله ﷺ وهو قلقان فقرأ رسول الله ﷺ عليه سورة الفتح،\nفاستغرب عمر وسأل رسول الله ﷺ:\nهو فعلا فتح؟!\nفقال له رسول الله ﷺ: نعم فتح\nوسورة الفتح آياتها رقيقة وهادئة وجميلة ودي حاجة فعلا تميزت بها سورة الفتح، اقرأوها بعد ما تقرأوا صلح الحديبية وانتم هتفهموا قصدي\nخلونا نشوف بعض الآيات كده وتعليقها على المواقف إللي حصلت،\nفاكرين الخمسين واحد من المشركين إللي جاءوا عشان يهجموا على معسكر المسلمين وهدفهم إنهم يشعلوا الحرب بين الطرفين ومحمد بن مسلمة مسكهم وسلمهم لرسول الله ﷺ وبعدين رسول الله ﷺ أطلقهم ربنا ذكر الحادثة دي في الآية:\n\"  الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ مَكَّةَ مِنْ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا\"\nوبعدين لما حصلت البيعة تحت الشجرة بيعة الرضوان ربنا قال عنها :\n\"إِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ فَمَنْ نَكَثَ فَإِنَّمَا يَنْكُثُ عَلَى نَفْسِهِ وَمَنْ أَوْفَى بِمَا عَاهَدَ عَلَيْهُ اللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا\"\nيعني في الحقيقة الصحابة بايعوا ربنا على الطاعة والثبات  وربنا مطلع عليهم، ومن شدة تأكيد العقد ده ربنا قال : يد الله فوق أيديهم يعني كأنهم صافحوا الله بأيديهم في المبايعة دي،\n☆وهو ربنا له يد\nأيوة ربنا له يدين وله قدمين وله وجه وبيتكلم وبيضحك وبيغار، لاااكن مش معنى كده إنه زي البشر\nاحنا بنتشابه في الاسم فقط لكن اليد دي عاملة إزاي أو ربنا بيضحك إزاي أو بيغار إزاي منعرفش\nزي لما نقول رجل الكرسي، هي رجل الكرسي زي رجل البشر\nطبعا لأ، ولكن التشابه في الاسم فقط، ولله المثل الأعلى في السماوات والأرض،\nفاحنا بنثبت لربنا ما أثبته لنفسه، ربنا قال إنه عنده يد خلاص يبقى عنده يد ،\nميقولش أنا عندي يد وبعدين ييجي واحد من البشر ميعرفش حاجة ويقول لربنا لا يارب انت معندكش يد، ده اليد بتاعتك معناها القدرة\nفربنا هو الأعلم بنفسه سبحانه، فلما يقول لنا حاجة خلاص نصدقها زي ما هي من غير ما نقعد نقول طب إزاي ونقعد نشبه أو نعطل أي صفة من صفاته سبحانه، \n\" لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ \"\nالصحابة إللي بايعوا رسول الله ﷺ كانوا فعلا صادقي الإيمان، ربنا عَلِم إللي في قلوبهم من صدق ويقين وثبات ووفاء عشان كده رضي عنهم، وتخيلوا بقى لما ربنا يرضى عن حد، أمنيتنا جميعا إن ربنا يرضى علينا،\nفتخيلوا إحساس الصحابة لما يسمعوا إن ربنا رضي عنهم\n\"لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمْ فَأَنْزَلَ السَّكِينَةَ عَلَيْهِمْ وَأَثَابَهُمْ فَتْحًا قَرِيبًا\"\nفربنا هيكافئهم بفتح قريب بعد الحديبية، وهو فتح خيبر وهنعرف قصة الفتح ده بعدين إن شاء الله،\nربنا بيكلم الصحابة بقى وبيقول لهم عن المشركين إللي منعوهم من الدخول لمكة وأد إيه كانوا متحمسين يدخلوا مكة للعمرة حتى ولو بالغصب والقتال وكانوا مجهزين الهدي،\n\"هُمُ الَّذِينَ كَفَرُوا وَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ وَالْهَدْيَ مَعْكُوفًا أَنْ يَبْلُغَ مَحِلَّهُ  \"\nلكن ربنا بيعرّفهم بقى ليه مخلاهمش يدخلوا مكة بالقوة  وقال :\nلو كنتم دخلتم وقاتلتم كنتم هتقتلوا رجال ونساء مؤمنين يكتموا إيمانهم انتم متعرفهمش،\nوساعتها كان هيصيبكم إثم وانتم مش عارفين، لكن لو كان تميّز المؤمنين عن المشركين كنت سمحت لكم بالدخول لمكة وقاتلتم المشركين،\n\"وَلَوْلَا رِجَالٌ مُؤْمِنُونَ وَنِسَاءٌ مُؤْمِنَاتٌ لَمْ تَعْلَمُوهُمْ أَنْ تَطَئُوهُمْ فَتُصِيبَكُمْ مِنْهُمْ مَعَرَّةٌ بِغَيْرِ عِلْمٍ \"\nفأخرنا العقوبة عنهم لحد ما نطلع منهم المؤمنين ويرجع كثير من المشركين إلى الإسلام، وهنشوف العمالقة إللي هيسلموا بعد كم شهر فقط من الصلح ده\n\"لِيُدْخِلَ اللَّهُ فِي رَحْمَتِهِ مَنْ يَشَاءُ لَوْ تَزَيَّلُوا لَعَذَّبْنَا الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابًا أَلِيمًا\"\nوحكت الآيات عن موقف سهيل بن عمرو وإنه أخذته الحميّة وهي الغرور والطيش وصمم إنه لا يكتب كلمة 《بسم الله الرحمن الرحيم》 ولا يكتب كلمة 《رسول الله》  \nوفي المقابل ربنا أنزل الاطمئنان والصبر على رسوله وعلى المؤمنين إللي معاه، \n\"إِذْ جَعَلَ الَّذِينَ كَفَرُوا فِي قُلُوبِهِمُ الْحَمِيَّةَ حَمِيَّةَ الْجَاهِلِيَّةِ فَأَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ \"\nأما بقى موقف عمر رضي الله عنه وسؤاله عن الرؤيا ربنا بيطمئن قلبه بقوله:\n\"لَقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالْحَقِّ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِنْ شَاءَ اللَّهُ آمِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا فَجَعَلَ مِنْ دُونِ ذَلِكَ فَتْحًا قَرِيبًا \"\nيعني الرؤيا إللي رسول الله ﷺ شافها كانت رؤيا حق، هتدخلوا المسجد الحرام وهتطوفوا بالبيت في أمان،\nفالصحابة لما سمعوا الآيات ارتاحوا واطمأنت نفوسهم، لكن لسه موضوع أبو جندل بن سهيل بن عمرو مضايقهم\nرجع رسول الله ﷺ للمدينة ومعاه الصحابة وخبر الصلح بدأ ينتشر بين الناس وإن رسول الله ﷺ رجع سالما وكمان حصل صلح بينه وبين قريش، فجاء الأعراب يعتذروا لرسول الله ﷺ إنهم مخرجوش معاه للعمرة عشان كانوا مشغولين بأموالهم وأولادهم، \nفنزلت الآية توضح موقفهم وأعذارهم الواهية\n\"سَيَقُولُ لَكَ الْمُخَلَّفُونَ مِنَ الْأَعْرَابِ شَغَلَتْنَا أَمْوَالُنَا وَأَهْلُونَا فَاسْتَغْفِرْ لَنَا \"\nالسبب الرئيسي إللي خلاهم ميخرجوش مع رسول الله ﷺ هو :\n\"بَلْ ظَنَنْتُمْ أَنْ لَنْ يَنْقَلِبَ الرَّسُولُ وَالْمُؤْمِنُونَ إِلَى أَهْلِيهِمْ أَبَدًا\"\nيعني همّ خافوا يخرجوا معاه لأنهم شافوا إن رسول الله ﷺ رايح يسلم نفسه للمشركين وهتحصل حرب هيُقتل فيها المسلمون كلهم.\nاحنا كده وصلنا لآخر السنة السادسة من الهجرة، وهنا هتبدأ مرحلة جديدة من الدعوة إلى الإسلام،\nالدعوة هتبقى عالمية\nرسول الله ﷺ أُرسل للثقلين الإنس والجن، فالدعوة لازم توصل لكل أهل الأرض، فبدأ رسول الله ﷺ بإرسال رسائل الدعوة إلى الإسلام لملوك الأرض، كِسْرى وقيْصر والنجاشي والمُقَوقس وغيرهم،\nفلأن إرسال الرسائل استمر لحد أوائل السنة السابعة من الهجرة فاحنا هنتكلم عن الرسائل دي بالتفصيل لما نتكلم عن السنة السابعة من الهجرة إن شاء الله\nبعد ما رجع رسول الله ﷺ للمدينة بعد صلح الحديبية بفترة بسيطة كم يوم بس جاءه رجل مسلم من مكة،\nواحد اسمه أبو بصير جاي هربان من التعذيب إللي كان بيحصل له في مكة،\nعرف يفك نفسه ويهرب من مكة وهاجر للمدينة، مشي على رجله خمسمائة كيلو لحد ما وصل للمسجد النبوي ودخل لرسول الله ﷺ وقال له أنا جاي مسلم مهاجر يا رسول الله، \nملحقش ياخد نفسه وإلا رجلين من قريش داخلين وراه وبيقولوا :\nالعهد الذي بيننا وبينك يا محمد، رجع لنا أبو بصير\nفقال لهم رسول الله ﷺ إنهم يأخذوه،\nهنا أبو بصير اتصدم\nبعد ما استطاع إنه يهرب من مكة وفضل مُطارد في الصحراء أيام والله أعلم بحاله كان بياكل إزاي ولّا بينام إزاي والتعب إللي كان فيه وبكل بساطة كده رسول الله ﷺ يسلمه للكفار\nوهو قال لرسول الله ﷺ:\nيا رسول الله يفتنوني في ديني، إزاي ترجعني ليهم\n هو مكنش يعرف عن العهد إللي كان بين رسول الله ﷺ وبين المشركين،\nفرسول الله ﷺ قال له:\nاحنا بيننا وبين قريش عهد ومنقدرش نخالف العهد ده، ارجع وربنا هيجعل لك ولأصحابك المستضعفين مخرجا\nوهنا مأساة أبو جندل تتكرر مرة ثانية ولكن بصورة أشد، ورسول الله ﷺ والصحابة مش قادرين يعملوا حاجة للمستضعفين دول\nالرجلين المشركين أخذا أبا بصير واتجهوا راجعين لمكة، وهم ماشيين بيريحوا في النص ومكنوش لسه بعدوا أوي عن المدينة، فوهم قاعدين السيف بتاع واحد من المشركين لمع كده في الشمس وهو ماسكه، فأبو بصير قال له:\nالسيف بتاعك ده حلو أوي وشكله قوي\nفالرجل المشرك قعد يتفاخر ويقول له أنا عملت بيه كذا وكذا وأبو بصير متفاعل معاه وراح قايله وريهولي كده\nفالمشرك أعطى السيف لأبو بصير، أول ما أبو بصير مسك السيف راح قاطع رقبة المشرك \nالمشرك الثاني عرف إنه هيتقتل هو كمان راح طالع جري على المدينة وأبو بصير وراه،\nوصل لرسول الله ﷺ في المسجد رسول الله ﷺ شاف منظره وهو جاي مرعوب فقال للصحابة :\nالرجل ده شاف الموت\nفجاء وراءه أبو بصير وقال لرسول الله ﷺ:\nيا رسول الله انت خلاص وفّيت بعهدك لهم وأنا ربنا نجاني منهم \nوخرج من عند رسول الله ﷺ، وهو خارج سمع أبو بصير رسول الله ﷺ يقول :\nويْلَ أمه مِسْعَرُ حربٍ لو كان معه رجال\nيعني لو هو معاه رجال هيشعلل الحرب، أبو بصير سمع الكلمة وانطلق ناحية ساحل البحر وسكن هناك،\nأبو جندل عرف يهرب من الأسر من مكة وعرف إن أبا بصير سكن عند ساحل البحر فراح يسكن معاه،\nبدأوا هم الاتنين يهجموا على قوافل قريش إللي بتعدي من المنطقة دي، وبقى كل إللي يُسلم ينضم لهم لحد ما كونوا \nعصابة، أي قافلة لقريش يهجموا عليها،\nوأصلا قريش كانت عملت المعاهدة عشان تضمن إن قوافلها تعدي، فكده بقوا في ورطة\nراحوا باعتين لرسول الله ﷺ خلاص احنا متنازلين عن الشرط بتاع إن إللي يأتيك من عندنا مسلم ترجعه لنا تاني، خلاص إللي يُسلم خده مش عايزينه بس نحل المشكلة دي،\nوبكده كسب رسول الله ﷺ المعاهدة من جميع الجهات، والفرق بين المعاهدة والتنازل عن الشرط كان أيام،\nوأرسل رسول الله ﷺ لعمر وأخبره بالخبر، وظهر لعمر ولكل الصحابة حكمة رسول الله ﷺ والفرج إللي جاء لأبو بصير وأبو جندل وغيرهم من المستضعفين\nوواحد من الصحابة اسمه سهل بن حُنَيْف كان بيقول للتابعين بعدين :\nأيُّها النَّاسُ اتَّهِمُوا رَأْيَكُمْ علَى دِينِكُمْ، \nيعني لما يكون في حاجة مش فاهمينها في الدين أو مش مستوعبينها اتهموا عقولكم ولا إنكم تتهموا أوامر الله أو رسوله،\nلقَدْ رَأَيْتُنِي يَومَ أبِي جَنْدَلٍ، ولو أسْتَطِيعُ أنْ أرُدَّ أمْرَ رَسولِ اللَّهِ ﷺ عليه لَرَدَدْتُهُ،\nيعني لو كان يقدر إنه يرد أمر رسول الله ﷺ بإن أبو جندل يرجع مع جيش المسلمين كان هيرده ومش هينفذ أمر رسول الله ﷺ وكان هيقاتل قريش ويرفض المعاهدة لأن مكنش شايف الحكمة إللي رسول الله ﷺ شايفها،\nوده يعلمنا احنا كمان إن مش كل حاجة شايفينها شر أو مش مستوعيبنها نرفضها أو ننكرها،\nلأننا زي ما شوفنا الموقف العصيب ده أخرج فتح مبين إزاي، ولسه هنشوف الأحداث بعدين كلها هتبقى في صالح المسلمين إزاي\n♡الجزء ده طويل معلش\n المنشور الجاي هيبقى مفاجأة إن شاء الله\n♡"}, {"n": 140, "l": "الجزء 114 | علامات الساعة الصغرى الجزء الأول", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_مائة_وأربعة_عشر\n#علامات_الساعة_الصغرى\n#الجزء_الأول \nكلامنا في الأجزاء الأخيرة إللي فاتت كان عن الغزوات والسرايا والمعاهدة مع قريش، \nيعني نقدر نقول إننا كنا مركزين على العلاقات الخارجية للدولة الإسلامية\nعايزين بقى نعيش شوية مع رسول الله ﷺ والصحابة في المدينة ونشوف رسول الله ﷺ كان بيعلمهم إيه عن الدين،\nمن الحاجات إللي رسول الله ﷺ كان بيعلمها للصحابة إنهم يؤمنوا بالغيب،\nوكان من الغيب ده يوم القيامة ويوم القيامة هو اليوم إللي الناس هتُبعث فيه بعد الموت وتتحاسب على أعمالها، \nوهو يوم محدش يعرف وقته امتى غير ربنا عز وجل، لا أنبياء ولا ملائكة، لكن اليوم ده هيأتي أكيد\nورسول الله ﷺ لما جاءه واحد من الأعراب يسأله متى الساعة رسول الله ﷺ قال له: ماذا أعددت لها؟\nفمش المهم إننا نعرف هي امتى لكن المهم إننا نستعد لها زي المسافر إللي بيستعد للسفر\n☆ملحوظة :\nميعاد يوم القيامة من الغيبيات الخمسة التي لا يعلمها إلا الله، والغيبيات الخمسة دي هي :\n◇يعلم إللي هيحصل للإنسان في حياته،\n◇يعلم إللي في الأرحام من ذكر أو أنثى،\n◇يعلم متى ينزل المطر ،\n◇يعلم متى يموت الإنسان، \n◇يعلم وقت الساعة أو يوم القيامة.\nقال تعالى:\n\"إِنَّ اللَّهَ عِندَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ ۖ وَمَا تَدْرِي نَفْسٌ مَّاذَا تَكْسِبُ غَدًا ۖ وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ ۚ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ \"\nومع إننا منعرفش امتى بالضبط ميعاد يوم القيامة لكن ربنا أخبرنا عن علامات لليوم ده، \nوده من رحمة ربنا بعباده عشان ينتبهوا من غفلتهم ويستعدوا للقاء الله، ربنا قال:\n\"فَهَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ أَنْ تَأْتِيَهُمْ بَغْتَةً فَقَدْ جَاءَ أَشْرَاطُهَا \"\nفالعلامات دي زي بالضبط كده العلامات إللي بتكون على طريق المسافر،\nلما نركب أي مواصلة ونشوف علامة مكتوب عليها فاضل كذا كيلو على المكان إللي احنا رايحينه فبنستعد للنزول كل ما نقرب للمكان ده،\nيعني لو واحد ركب قطار ومدة سفره ساعتين أكيد هيبقى قاعد وواخد راحته بعكس لما يشوف علامة بتقول له خلاص انت نازل المحطة الجاية بيبدأ يستعد ويلم حاجاته عشان ينزل،\nكذلك أشراط الساعة أو علامات الساعة، ربنا جعل لنا علامات عشان نستعد، عشان كل شوية نفتكر إن في يوم قيامة وإننا مهما عشنا فاحنا هنرجع لربنا في يوم من الأيام ونقف بين يديه ونتحاسب على كل صغيرة وكبيرة\nفالهدف الرئيسي من علامات الساعة هو الاستعداد، مش إننا ننشغل بيها وتكون هي شغلنا الشاغل ونقعد ندور عليها\nوعلامات الساعة بتنقسم لقسمين:\nعلامات ساعة صُغرى وعلامات ساعة كُبرى،\n◇علامات الساعة الصغرى هى العلامات إللي بيتكرر حدوثها ومستمرة مش بتنقطع وبيكون بينها وبين يوم القيامة زمن،\nومش كل الناس بيحسوا بيها لأنها ممكن تحصل في مكان ومكان تاني لأ.\n◇أما علامات الساعة الكبرى هي علامات غير مألوفة وعظيمة كل الناس بيحسوا بيها وبيشوفوها وبتكون قريبة جدا من يوم القيامة،\nوكل العلامات بتيجي وراء بعضها زي حبات الخرز إللي في العقد إذا انقطع، شوفوا الحبات بتقع وراء بعضها إزاي بسرعة، كذلك علامات الساعة الكبرى بتيجي بسرعة وراء بعضها\nقبل ما نتكلم بالتفصيل عن العلامات دي عايز أفكركم بنقطتين :\n♡أولا :\n كل الكلام إللي هقوله عن علامات الساعة هو من الأحاديث الصحيحة فقط مش هجيب أي حديث من الأحاديث الضعيفة، وشرح الأحاديث هو كلام الصحابة والتابعين والعلماء يعني أنا فقط بنقل لكم الكلام لكن بأسلوب مُبسط مش أكثر،\n \n♡ثانيا:\nبأكد على إن الهدف من السيرة النبوية مش إننا نحكي قصة وخلاص،\nأنا عايزاكم تعيشوا مع رسول الله ﷺ والصحابة وتعرفوا حياتهم كانت إزاي سواء وقت الغزوات والسرايا أو الحياة اليومية إللي كانوا بيعيشوها مع رسول الله ﷺ في المدينة بمشاكلهم وفرحهم وحزنهم عشان نحبهم ويبقى سهل علينا إننا نعمل زيهم على أد ما نقدر عشان ربنا يحشرنا معاهم يوم القيامة،\nوكمان بالطريقة دي نقدر نتعلم الدين من رسول الله ﷺ زي ما كان بيعلمه للصحابة بكل بساطة\nنكمل كلامنا عن علامات الساعة، \nعلامات الساعة الصغرى في منها إللي حصل وخلاص خلص وفي منها إللي حصل ومازال مستمر وفي منها إللي لسه محصلش،\nرسول الله ﷺ قال للصحابة وهو بيكلمهم عن يوم القيامة:\n\"بُعِثْتُ أَنَا وَالسَّاعَة كَهَاتَيْن\" وأشار بأصبعيه السبابة والوسطى\nيعني رسول الله ﷺ بيقول للصحابة إن أول علامة من علامات الساعة الصغرى هي بعثته ﷺ، \nوالمسافة بين بعثته وبين قيام الساعة زي المسافة بين السبابة والوسطى كده\nفهو النبي الأخير ومفيش أي أنبياء بعده وييجي بعده القيامة ونهاية الدنيا.\n☆طبعا السؤال إللي محيرنا كلنا، إزاي يعني بعثة رسول الله ﷺ قريبة جدا من الساعة كده وعدّى دلوقتي أكثر من ألف وأربعمائة سنة ولسه مفيش حاجة حصلت والله أعلم فاضل لسه كمان كم سنة\nالإجابة بكل بساطة إننا لازم نراعي النسبة الزمنية واحنا بنتكلم، يعني الحساب الزمني عندنا غير الحساب الزمني عند ربنا، مش ربنا بيقول إن اليوم عند ربنا كألف سنة عندنا:\n\"وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ \"\nيبقى ده معناه إن الألف وأربعمائة سنة دول يادوب ميجوش يوم ونص عند ربنا \nوربنا نفسه قال:\n\"إِنَّهُمْ يَرَوْنَهُ بَعِيدًا وَنَرَاهُ قَرِيبًا \" \nهو بالنسبة لنا بعيد عشان العامل الزمني مختلف عندنا لكن هو قريب عند ربنا، \nيعني لو افترضنا جدلا يعني إن عُمر الدنيا لسه فيه كمان ألف وأربعمائة سنة يعني ثلاثة آلاف سنة تقريبا يبقى المجموع عند ربنا ثلاثة أيام فقط،\nوكمان الزمن الباقي من الدنيا بالنسبة للأمم السابقة زمن قليل، يعنى لو مثلا ميعاد قيام الساعة غروب الشمس \nفالأمم السابقة قعدت في الدنيا من وقت الفجر لحد وقت العصر،\nوأمة الإسلام كان وقتها من العصر لحد المغرب، \n قال رسول الله ﷺ:\n\"إِنَّمَا بَقَاؤُكُمْ فِيمَا سَلَفَ قَبْلَكُمْ مِنْ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ\"\nففترة بعد العصر لغروب الشمس فترة قليلة جدا بالنسبة للفترة الزمنية من الفجر للعصر، وهو ده حال الباقي من الدنيا،\nيبقى كده مفيش أي إشكال لما رسول الله ﷺ يقول بُعثت أنا والساعة كهاتين\n1◇يبقى خلاص كده أول علامة هي بعثة رسول الله ﷺ.\n2◇العلامة الثانية: انشقاق القمر\n\"اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ\"\nواحنا اتكلمنا بالتفصيل في الجزء الأربعين عن معجزة انشقاق القمر ممكن ترجعوا لها عشان تفتكروا الأحداث.\n3◇العلامة الثالثة زي ما رسول الله ﷺ قال لواحد من الصحابة اسمه عَوْف بن مالك هي: موت النبي ﷺ،\nقال رسول الله ﷺ لعَوْف:\nأُعدُدْ ستًّا بين يدي الساعةِ : \nمَوتي ؛\n ثم فتحُ بيتِ المقدسِ ،\n ثم مُوتَانِ يأخذ فيكم كقُعاصِ الغنمِ ،\nثم استفاضةُ المالِ حتى يُعطَى الرجلُ مائةَ دينارٍ ، فيظلُ ساخطًا ،\n ثم فتنةٌ لا يبقى بيتٌ من العربِ إلا دخلَتْه ، \nثم هُدنةٌ تكون بينكم وبين بني الأصفرِ ، فيغْدرون ، فيأتونكم تحت ثمانينَ غايةً ، تحت كلِّ غايةٍ اثنا عشرَ ألفًا.\nيعني رسول الله ﷺ بيقول إن في ست علامات هيحصلوا قبل قيام الساعة، طبعا مش دي كل العلامات في علامات تانية بس الستة دول رسول الله ﷺ قالهم مع بعض وأولهم موته ﷺ،\nوقصة موته هنعرفها بعدين إن شاء الله وهنشوف إزاي إن موته كان أعظم مصيبة في حياة الصحابة وفي حياة الأمة كلها،\nخلونا ناخد العلامات إللي في الحديث واحدة واحدة،\n4◇العلامة الرابعة زي ما جاءت في الحديث : هي فتح بيت المقدس، \nفي وقت رسول الله ﷺ  بيت المقدس كان تحت حكم الرومان، فهو بيقول إن المسلمين هيفتحوا بيت المقدس وهيبقى تحت حكم المسلمين بعدين،\nوالعلامة دي حصلت فعلا في عهد عمر بن الخطاب رضي الله في سنة ستة عشر أو سبعة عشر من الهجرة وبقى بيت المقدس تحت حكم المسلمين، \nوطبعا فتح بيت المقدس غير تحرير بيت المقدس، يعني عمر بن الخطاب رضي الله عنه فتحه أول مرة، وصلاح الدين الأيوبي حرر بيت المقدس بعدين لما وقع في أيدي النصارى،\nففي فرق بين الفتح والتحرير، \nفالفتح هو إللي من علامات الساعة\n5◇العلامة الخامسة مُوتَان أو مَوَتان يحصل في الأمة، يعني موت جماعي يصيب عدد كبير من الناس زي الغنم إللي بيصيبه مرض وفجأة يقعوا كلهم أموات،\nوالعلامة دي حصلت بعد فتح بيت المقدس سنة ثمانية عشر للهجرة،\nحصل وباء أو طاعون في قرية صغيرة اسمها عَمْوَاس بين الرّمْلة وبيت المقدس وبعدين الوباء ده انتشر في بلاد الشام ومات بسببه عدد كبير جدا من المسلمين وعدد كبير من الصحابة زي أبو عبيدة عامر بن الجراح أمين الأمة ومعاذ بن جبل، وسهيل بن عمرو وابنه أبو جندل.\nحتى يُقال إن إللي ماتوا من المسلمين بسبب الوباء ده كانوا خمسة وعشرين ألف، واتسمى الوباء ده باسم طاعون عَمْواس.\n☆ملحوظة : \nبلدة عمواس مش مجودة دلوقتي لأن اليهود هدموها سنة 1967 وشردوا أهلها وبنوا مكان القرية دي غابة بأموال المتبرعين من اليهود الكنديين وسموها منتزه كندا.\n6◇العلامة السادسة: استفاضة المال والاستغناء عن الصدقة، يعني المال هيبقى كثير جدا مع الناس لدرجة إنهم  مش هيلاقوا حد ياخد الصدقة بتاعتهم،\nفي حديث تاني لرسول الله ﷺ بيقول فيه إن الرجل هيبقى كفه مليان ذهب أو فضة صدقة ويقعد يدور على حد ياخد الصدقة دي مش هيلاقي،\nوالعلامة دي تحققت، ففي عهد الصحابة وانتشار الفتوحات الإسلامية وفتح بلاد فارس والروم المال بقى كثير جدا،\nوفي عهد عمر بن عبد العزيز فاض المال، يعنى بقى في فائض كبير في المال وبقى الواحد يعرض الصدقة على الناس وميلاقيش إللي يقبلها،\nوالعلامة دي هتحصل مرة ثانية في آخر الزمان في زمن المهدي وبعد ما ينزل عيسى عليه السلام،\nوهنعرف إللي هيحصل وقتها لما نتكلم عنهم إن شاء الله\n7◇العلامة السابعة: ظهور الفتن،\nوالفتنة يعني الابتلاء والاختبار، فهيحصل للناس اختبارات كثيرة تُزلزل الإيمان في القلوب،\nورسول الله ﷺ في حديث تاني بيقول عن الفتن :\nإن بين يدي الساعة فتنا كقِطَع الليل المظلم، يعني الفتنة في شدة وقوتها زي الليل شديد السواد،\nورسول الله ﷺ بيتكلم عن سواد الليل إللي هو شافه بتاع الصحراء إللي مفهوش أي ضوء خالص مش سواد الليل بتاعنا إللي الأنوار مخلية له ضوء فالواحد يستأنس بيه،\nسواد الليل بتاع الصحراء مرعب فعلا، وإللي سافر بالليل في طريق صحراوي من غير ضوء على الطريق هيعرف معنى قطع الليل المظلم،\nفالفتن إللي هيتعرض لها المؤمنين زي الليل المظلم ده،\nلدرجة إن الواحد يبقى الصبح مؤمن وبالليل يكفر وده بسبب إنه هيبيع دينه بعَرَض من الدنيا،\nوأظن احنا شايفين الموضوع ده في الواقع بتاعنا، كم واحد كان مسلم وعشان اتعرض لابتلاء ترك الدين وألحد،\nوكم واحد ضحى بدينه وباعه عشان شغلانة أو عشان مال أو عشان منصب،\nوكم واحد كان ملتزم بتعاليم الإسلام وبسبب الابتلاءات ترك الالتزام، وإللي قلعت النقاب وبقت تلبس بناطيل وإللي كان بيصلي وساب الصلاة وهكذا،\nوالفتن مستمرة لحد قيام الساعة وكل ما بنقرب من يوم القيامة كل ما الفتن بتكون أصعب وأشد، وكل فتنة يتعرض لها المؤمن يقول هذه مُهلكتي، يعني خلاص الفتنة دي هي إللي هتضيعني، \nعشان كده رسول الله ﷺ بيقول لنا :\nبادروا بالأعمال الصالحة فتنا كقطع الليل المظلم ، \nيعني عشان الواحد ينجوا من الفتن والاختبارات الشديدة دي محتاج إنه يُسارع ويعمل الأعمال الصالحة قبل ما يتعرض للإبتلاء ؛ \nلأن صنائع المعروف تقي مصارع السوء، يعني إللي عنده رصيد من الأعمال الصالحة هو إللي ربنا هينجيه ويحفظه من الفتن\nوطبعا مع الدعاء والتعوّذ من الفتن ما ظهر منها وعارفين إنه فتنة وما بَطَن يعني المختفي ومش عنه عارفين إنه فتنة.\n☆وإللي عايز ينجو من النار ويدخل الجنة يعمل زي ما رسول الله ﷺ قال :\n\"مَن أحَب أن يُزحزَح عن النار ويدخل الجنة ، فلتأتِه منيَّتُه وهو يؤمن بالله واليوم الآخر، وليأتِ إلى الناس الذي يحب أن يُؤْتى إليه\"\nيعني احنا عندنا جزئين :\n◇الجزء الأول : \nإن الواحد فينا يموت على الإيمان بالله واليوم الآخر ، والإيمان قول باللسان وتصديق بالقلب وعمل بالجواح، فاللي بيؤمن بالله واليوم الآخر فعلا مش مجرد كلام لازم يعمل الأعمال الصالحة عشان يموت على الإيمان ده.\n◇الجزء التاني :\nإننا نعامل عموم الناس زي ما بنحب الناس تعاملنا، ونعمل معاهم إللي نحب إنه يتعمل معانا،\nفننصح للناس زي ما ننصح لنفسنا ،ونكره للناس ما نكرهه لنفسنا ، منكذبش عليهم ، ولا نغشهم ولا نخدعهم ، ولا نحب لهم الشر،\nفلما نتعامل مع الناس يكون ميزان المعاملة : هل احنا نحب إن الناس يعاملونا بالمعاملة دي أو لأ،\nفنعاملهم باللطف زي ما نحب إنهم يعاملونا باللطف واللين ، وبحُسن الكلام وبحُسن المنطق واللين ،وإللي هيعمل كده هو ده إللي هيُزحزح عن النار ويدخل الجنة\n8◇العلامة الثامنة من علامات الساعة:\n ظهور مُدّعي النبوة،\nيعني بعد رسول الله ﷺ في ناس هتدعي النبوة منهم حوالي ثلاثين واحد هيكون لهم أتباع كثيرون ويشتهروا بين الناس وهيكون لهم قوة،\nومن الثلاثين دول أربعة نساء، وفي أواخر عهد رسول الله ﷺ ظهر أول مُدعي للنبوة وهو مُسَيْلِمة الكذاب،\nوظهر بعد مسيلمة باقي الثلاثين.\n9◇العلامة التاسعة: انتشار الأمن،\nكان في عهد رسول الله ﷺ قُطاع الطرق كثير وكان في قبائل كاملة تقطع الطريق،\nفرسول الله ﷺ قال إن الساعة لن تقوم حتى يسير الراكب لوحده من العراق إلى مكة لا يخاف إلا ضلال الطريق،\nوالعلامة دي حصلت في زمن الصحابة لما الإسلام انتشر في البلاد وانتشر العدل.\n10◇العلامة العاشرة إللي جاءت في الحديث إللي قلناه من شوية : الفتنة التي تدخل كل بيوت العرب،\nقال العلماء إن الفتنة دي كانت الفتنة إللي حصلت بين الصحابة بعد مقتل عثمان بن عفان رضي الله عنه،\nوطبعا الموضوع ده كبير ومحتاج شرح مش هينفع ألخصه في كلمتين\nفي علماء من العصر الحديث قالوا إن الفتنة دي هي فتنة وسائل الإعلام والتواصل الاجتماعي، لأنها بتدخل كل بيوت المسلمين حتى في الأماكن الصحراوية،\nوهم استنتجوا الكلام ده من جمع أحاديث رسول الله ﷺ مع بعضها،\nيعني في حديث لرسول الله ﷺ يقول عن الفتنة دي\nإنه يدخل حَرّها بيت كل مسلم،\nيعني يدخل أذى الفتنة دي بيت كل مسلم فهي تعم المسلمين ومش خاصة بالعرب فقط،\nوفي حديث تاني قاله حذيفة بن اليمان رضي الله عنه:\nلَيُوشِكَنَّ أَنْ يُصَبَّ عَلَيْكُمَ الشَّرُّ مِنَ السَّمَاءِ حَتَّى يَبْلُغَ الْفَيَافِيَ .\nقَالَ : قِيلَ : وَمَا الْفَيَافِيُ يَا أَبَا عَبْدِ اللهِ ؟\nقَالَ : الأَرْضُ الْقَفْرُ .\nواحنا بنشوف الناس في الصحاري ومعاهم الموبايلات والنت  وبيوصل لهم كل شر من أغاني وأفلام ومسلسلات وغيرها\nدول كانوا أول عشر علامات من علامات الساعة الصغرى،\nإن شاء الله المرة الجاية نكمل الجزء الثاني من علامات الساعة الصغرى، \nياريت طبعا تنشروا العلامات دي عشان الناس تاخد بالها \n♡"}, {"n": 141, "l": "الجزء 115 | علامات الساعة الصغرى الجزء الثاني", "u": "", "t": "عشان بس لما يطلع شيخ يحلل ويحرم ع مزاجو مش تبقو تمشو وراه ابقو شوفو واقرئو سيدنا محمد كان بيعمل اي واعملو زيو مش تطلع وحدا تقول حلال البنت تخرج مع خطيبها من غير محرم \n \n#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_مائة_وخمسة_عشر\n#علامات_الساعة_الصغرى\n#الجزء_الثاني\nاتكلمنا المرة إللي فاتت عن أول عشر علامات من علامات الساعة الصغرى، وهم عالسريع كده :\nبعثة رسول الله ﷺ وانشقاق القمر وموت رسول الله ﷺ، وفتح بيت المقدس ومُوتَان يصيب الأمة، واستفاضة المال، وظهور الفتن وظهور مُدعي النبوة، وانتشار الأمن والفتنة إللي تدخل بيوت العرب.\n11◇هندخل في العلامة الحادية عشر وهي: خروج نار من أرض الحجاز، قال رسول الله ﷺ:\n\"لا تقوم الساعة حتى تخرج نار من أرض الحجاز، يُضيء لها أعناق الإِبل ببُصرى\"\nوقال في حديث تاني:\n\"لا تقوم الساعة حتى تخرج نار من رُومان أو رَكُوبة يُضيء منها أعناق الإبل بِبُصرى\"\nوالكلام ده معناه إن الأرض ستنشقّ ويخرج منها الحمم الملتهبة، وإن النار دي هتكون عظيمة لدرجة إن الناس في الشام هيشوفوها، وبُصرى هي مدينة حُوران في سُوريا،\nوالعلامة دي حصلت فعلا في عهد الإمام النووي سنة ستمائة وأربع وخمسين للهجرة،\nوفي علماء كثير تكلموا عنها زي الإمام القرطبي وابن كثير وغيرهم،\nقالوا إن النار دي كان بدايتها إن حصل زلزال شديد جدا للأرض من ليلة الأربعاء لحد يوم الجمعة، لدرجة إن الناس إللي كانوا في السجد النبوي كانوا بيسمعوا صوت الحديد إللي في منبر رسول الله ﷺ من شدة الزلزلة، \nوكانت الزلزلة دي لها صوت زي صوت الرعد القاصف، وطبعا الناس كانوا في قمة الرعب\nوبعد الزلزلة دي ظهرت نار كبيرة جدا قريبة من دِيار بني قريظة قرب المدينة،\nالناس إللي كانوا داخل المدينة كانوا شايفين النار دي كأنها عندهم داخل المدينة،\nوالنار كانت مرتفعة جدا في السماء وبقى في أودية تسيل بالنار والجبال بقت تسيل نار،\nانتم أكيد شوفتم البراكين لما بتفور وتسيل بتعمل إيه في الصخور والجبال والأرض،\nأهه إللي حصل ده كان فوران بركاني في منطقة الحَرّة وهي منطقة مليئة بالتكوينات البركانية السوداء،\nوالصخور البركانية دي اتكونت بسبب الأنشطة البركانية القديمة،\nفرسول الله ﷺ تنبأ إن هيحصل نشاط بركاني قبل قيام الساعة، وفعلا بعد ما قال كده بستمائة سنة تحقق كلامه ﷺ، \nوبعدين ييجي واحد ويتجرأ ويُكذب رسول الله ﷺ ويقول إنه مش رسول وإن هو إللي اخترع الدين وإن مفيش حاجة اسمها إله\nهو في كذبة ممكن تقعد أكثر من ألف وأربعمائة سنة؟!!\nطيب والحاجات إللي قال إنها هتحصل وفعلا حصلت وهتحصل ، كل ده برده صدفة أو كذب\n\"وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ ظُلْمًا وَعُلُوًّا \"\nالباحث عن الحق يكفيه دليل، وإللي عايز يمشي على هواه مش هتكفيه كل الأدلة على وجه الأرض \n\"أَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا\"\nالمهم، \nالنار الكبيرة بقى يَسِيل منها أودية من نيران واتجهت ناحية المدينة وأهل المدينة فزعوا منها جدا ومبقوش عارفين يعملوا إيه،\nومع النار دي حصل كسوف للشمس وبعدها خسوف للقمر،\nيعني آيات وراء بعضها والناس خايفة،\nفبدأ الناس يتوبوا ويتركوا المعاصي، ويدعون الله عزوجل،\nويتقربوا إليه بالطاعات،\nودخل أهل المدينة إلى المسجد النبوي مستغفرين تائبين إلى ربهم، وبات الناس بين مصلٍّ وتالٍ للقرآن، وراكع وساجد،\nواستمر ثوران البركان والنار المشتعلة ثلاثة أشهر وبعدين  النار دي انطفأت،\nوكل مَن ذَكر النار دي من المؤرخين والعلماء يقول في آخر كلامه: ولا أقدر أشرح وصفها على الكمال،\nيعني مع كل الوصف إللي وصفوه مش قادرين يعبروا النار دي عاملة إزاي من شدتها والأهوال إللي كانت فيها\nطبعا وَصْف العلماء فيها كثير جدا مش هقدر أقوله كله، أنا قلت المختصر المفيد \n☆ملحوظة مهمة بقى،\nالنار إللي خرجت في أرض الحجاز دي غير النار إللي هتخرج في آخر الزمان وهتقود الناس إلى أرض المحشر،\nدي حاجة ودي حاجة تانية خالص، النار التانية دي هتخرج من قعر عدن في اليمن وهي من علامات الساعة الكبرى وهنتكلم عنها إن شاء الله لما ييجي وقتها\n12◇العلامة الثانية عشرة: ضياع الأمانة، جاء رجل من الأعراب وسأل رسول الله ﷺ عن ميعاد يوم القيامة فقال له رسول الله ﷺ:\n\" إذا ضُيِّعت الأمَانَة فانتظر السَّاعة. فقال الأعرابي :\n كيف إضاعتها؟\n قال: إذا وُسِّد الأمر إلى غير أهله فانتظر السَّاعة\"\nوالكلام ده معناه إن الناس هييجي عليهم زمن يكونوا في مكان مش مكانهم ولا يستحقوا يكونوا فيه،\nتلاقي رئيس دولة مينفعش للرئاسة، نلاقي مدرس بيشتغل في مدرسة مينفعش للتدريس، \nنلاقي موظف في مصلحة مينفعش للشغل، ولكن كل هؤلاء أخذوا العمل عن طريق الواسطة والرشاوي والأمور الغير المشروعة،\nوطبعا للأسف احنا شايفين تضييع الأمانة في واقعنا عامل إزاي، وبنسمع عن إللي بيزور شهادات والرشاوي إللي بتندفع \nوهييجي يوم تُرفع الأمانة من قلوب الناس، والرجل إللي كان أمين في يوم من الأيام هيصحى ويبقى خائن وتُرفع الأمانة من قلبه،\nوده هيحصل  للي مبقاش يخشى الله وبقى إيمانه ضعيف، وخالط أهل الخيانة فبقى خائن زيهم،\nوطبعا كل ده بيدل على إن الناس ساعتها مبقتش مهتمة بدينها، وده بيرتبط بعلامتين تانيين للساعة وهما : \nانتشار الجهل وقلة العلم، ومجيء السنون الخداعات\n13◇العلامة الثالثة عشرة : انتشار الجهل ورفع العلم \nوده بيكون بقبْض العلماء يعني موتهم، \nقال رسول الله ﷺ:\n\" إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنْ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا \"\nمفيش علماء ربانيين يعلموا الناس الدين الصح،\nفالناس إما تبعد عن الدين وتضل أو إنهم يتبعون رؤوسا جُهّالا، \nيعني ناس مشهورين جهلة معندهمش علم وبيفتوا الناس وبيضلوهم، أو عندهم علم غلط فبيضلوا الناس بفتاويهم والناس مبتصدق تسمع فتاوى على مزاجها فيتبعوها\nوالموضوع ده بقى منتشر جدا في الفترة الأخيرة خصوصا من بعض شيوخ موقع الآسك إللي بيفتوا بجهل وبيخالفوا الأدلة الصحيحة وبيحللوا النمص وغيره،\nربنا يهديهم بجد\nالناس إللي زي كده رسول الله ﷺ قال عنهم :\n\"دعاة على أبواب جهنم من أجابهم إليها قذفوه فيها، فقال له حذيفة رضي الله  عنه: \nيا رسول الله صفهم لنا، قال: هم من جلدتنا ويتكلمون بألسنتنا\"\nهتلاقوا الناس دي بيتكلموا بالقرآن والسنة ولكن للأسف بيحرّفوا الكلام عن معناه الصحيح بسبب جهلهم لأنهم مأخذوش العلم عن الصحابة وعن العلماء،\nوللأسف في ناس كثير بيتّبعوا كلامهم، وإذا حد حاول يصلح الخطأ بتاعهم ويجيب كلام الصحابة والعلماء يرفضوا الكلام لأنه مش موافق لهواهم أو لأن الكلام غريب عليهم أو...أو...\nكل واحد بيفسر القرآن والأحاديث بمزاجه والأصل إننا نتبع القرآن والسنة بفهم الصحابة والتابعين وتابعي التابعين؛\nلأن الصحابة هم إللي نَزل عليهم القرآن وطبقوه ورسول الله ﷺ أقرهم على فهمهم وفعلهم\nومع إن لسه في علماء ربانيين لكن قليلون والناس مش عايزة تسمع لهم بسبب الفتن إللي حصلت وبقينا في السنين الخدّاعات التي يُصَدق فيها الكاذب ويُكذب فيها الصادق ويُؤتمن فيها الخائن ويُخوّن فيها الأمين،\nشايفين إزاي الناس ماشية وراء كلام شيوخ مُعينين أقل ما يُقال عنهم فعلا إنهم جهلة ولو حاولنا نقول كلام لشيوخ قضوا عمرهم كله في العلم والدعوة اتهموهم بالنفاق والكذب والخداع والخيانة عشان الكلام بتاعهم مش على هواهم؟!\n14◇والسنون الخداعات هي العلامة الرابعة عشرة من علامات الساعة الصغرى،\nوعشان نخرج من المتاهة دي ونتبع الحق مطلوب مننا ثلاثة أمور : الصدق والدعاء وعرض الفتوى على القلب،\nيعني نكون صادقين في إننا عايزين نتبع الحق فعلا، \nوندعي ربنا إنه يُبصّرنا بالحق ويرزقنا اتباعه وساعتها لما نسمع فتوى والفتوى فيها مشكلة قلبنا مش هيبقى مرتاح وهندور على الصح وربنا هيدينا لمعرفة الحق\n15◇العلامة الخامسة عشرة : ظهور الرُّوَيْبِضَة\nالرويبضة ده هو الرجل التافه أو الفاسق أو السّفِيه وبيتكلم في أمر العامة،\nيعني واحد مش نافع في أي حاجة تلاقيه طالع على القنوات الفضائية بيتكلم في الدين ويفتي،\nتلاقي واحدة متعرفش أي حاجة في الدين وعمالة تفتي على مواقع التواصل الاجتماعي وتقول حلال وحرام، \nوكل ده بسبب قلة العلم واتخاذ الناس رؤوسا جهال\nوصدقوني الوضع الحالي مختلف تماما عن خمسة وعشرين سنة فاتت، الدين كان له هيبة أكثر من كده ومكنش حد يتجرأ يتكلم في الدين زي ما الناس بتعمل دلوقتي،\nوإللي هيعيش منكم كمان خمسة وعشرين سنة هيشوف العجب\nهنكمل الجزء الجاي إن شاء الله."}, {"n": 142, "l": "الجزء 116 | علامات الساعة الصغرى الجزء الثالث", "u": "", "t": "مش عارفه اقول اي اقرئو انتو حرفيآ كل العلامات دي بنشوفها حالياً وانتو مش واخدين بالكم انها من علامات الساعه \n#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_مائة_وستة_عشر\n#علامات_الساعة_الصغرى\n#الجزء_الثالث\nاتكلمنا في الجزئين إللي فاتوا عن خمسة عشر علامة من علامات الساعة الصغرى، هنتكلم عن ست علامات وراء بعض في حديث لرسول الله ﷺ وكلهم فعلا حصلوا ، قال رسول الله ﷺ:\n\" أخاف عليكم ستًّا:\n إِمارة السفهاء، وسفك الدم، وبيع الحكم، وقطيعة الرحم، ونَشْواً يتخذون القرآن مزامير، وكثرة الشُّرَط\"\nهناخدهم واحدة واحدة، فالعلامة السادسة عشر هي:\n16◇إمارة السفهاء:\nقال رسول الله ﷺ لمعاذ بن جبل رضي الله عنه:\nأعاذك الله من إمارة السفهاء، قال معاذ: وما إمارة السفهاء؟\n قال رسول الله ﷺ:\nأمراء يكونون من بعدي، لا يهتدون بهُدَاي، ولا يستَنُّون بسنتي، فمن صدّقهم بكذبهم وأعانهم على ظلمهم فأولئك ليسوا مني ولستُ منهم، \nولا يَرِدُون عليَّ حوضي، ومن لم يُصدقهم بكذبهم ولم يعنهم على ظلمهم فأولئك مني وأنا منهم وسَيِردون عليَّ حوضي\"\nوالسفيه هو ناقص العقل الجاهل علما وعملا، فلما يكون واحد بالمواصفات دي ويتولى الإمارة هيقع في الكذب والخداع والظلم، ورسول الله ﷺ وصفهم بإنهم لا يتبعون سنته ومش بيعملوا زي ما كان بيعمل،\nونظرة واحدة على الواقع بتاعنا وانتم هتشوفوا أمثلة على الأمراء السفهاء إللي حاكمين المسلمين\nوطبعا لما يكون الحاكم سفيه ويبقى هو الآمر الناهي هيقود الناس لكل شر ويفتح عليهم أبواب الفتن،\nيفتح عليهم أبواب الزنا وشرب الخمر والسرقة والاختلاط بين الرجال والنساء في كل مكان، وطبعا مش محتاجة أجيب لكم أمثلة انتم شايفين بعنيكم إللي بيحصل\nفالأمراء السفهاء إللي حاكمين المسلمين دلوقتي وجودهم علامة من علامات الساعة الصغرى،\nفرسول الله ﷺ بيحذر معاذ وبيحذرنا سواء العلماء أو عوام الناس من إنهم يساعدهوهم ويصدقوهم ويعينوهم على ظلمهم وكذبهم وإلا فإن رسول الله ﷺ هيتبرأ من إللي هيعينهم ويتبعهم ومش بس مش هيشرب من حوض رسول الله ﷺ لأ ده حتى مش هيقرّب أصلا من الحوض \nوطبعا لما الأمراء السفهاء يتولون أمور المسلمين النتيجة هتكون سفك الدماء وكثرة القتل، ودي العلامة السابعة عشر:\n17◇سفك الدماء وكثرة القتل،\nورسول الله ﷺ بيقول في حديث تاني :\nوالذي نفسي بيده ليأتينَّ على الناس زمان لا يدري القاتل في أي شيء قَتل ولا يدري المقتول على أي شيء قُتل\"\nفبسبب كثرة القتل والتساهل فيه؛ القاتل مش عارف هو قَتل ليه ولا المقتول ليه قُتل،\nكم مرة سمعنا إن فلان قتل ابن فلان عشان ينتقم منه،\nأو الناس إللي كل يوم بتُقتل ظلما وعدوانا سواء في السجون أو في قصف أو في الشوارع أو...أو...\nالقتل دلوقتي بقى لأتفه الأسباب،\nوهو ده كثرة الهَرْج إللي رسول الله ﷺ قال عليه في الحديث :\n\"يتقارب الزمان، وينقص العمل وفي رواية العلم، ويُلقى الشّح، وتظهر الفتن، ويكثر الهرج، قالوا: يا رسول الله أيُّما هو؟ \nقال: القتل القتل\"\nوهنا نتعلم فائدة مهمة، وهي إننا نهتم بأمر العبادة في زمن الفتن والقتل،\nقال رسول الله ﷺ : \"العبادة في الهرج كهجرة إليّ\"\nيعني إللي يعبد ربنا في زمن الفتن والقتل والغفلة يأخذ أجر وثواب الهجرة إلى رسول الله ﷺ، والهجرة أعلى الطاعات منزلة عند الله عز وجل\nوالعبادة هي اسم جامع لكل ما يحبه الله من الأفعال الظاهرة والباطنة، الأفعال الظاهرة زي :\nالصلاة والصياة والزكاة والحج والذكر وبر الوالدين والإحسان للجار وصلة الأرحام والوفاء بالعهود والأمر بالمعروف والنهي عن المنكر، ولبس الحجاب الشرعي الصحيح،\nوالأفعال الباطنة زي:\nحب الله ورسوله وخشية الله والإنابة إليه وإخلاص الدين له والصبر لحكمه والشكر لنعمه والرضى بقضائه والتوكل عليه والرجاء لرحمته والخوف من عذابه.\n◇بالنسبة لتقارب الزمان والشُّح هنتكلم عنهم إن شاء الله كمان شوية.\n☆سؤال بقى : ليه العبادة في وقت الغفلة والفتن وكثرة القتل تعادل ثواب الهجرة إلى رسول الله ﷺ \n◇أولا:\nلأن الناس في الوقت ده بينشغلوا عن العبادة ويغفلوا عنها، ومحدش بيتفرغ لها غير الأفراد.\n◇ثانيا :\n الناس في زمن الفتن يتَّبعون أهواءهم، ولا يرجعون إلى دين؛ فحالهم بيبقى شبيه بحال الناس في الجاهلية،\n فإذا انفرد واحد من بين الناس وتمسك بدينه وعبد ربه واتبع ما يرضيه وتجنب ما يغضبه كان بمنزلة مَن هاجر من بين أهل الجاهلية إلى رسول الله ﷺ مؤمنًا به، متبعًا لأوامره، مجتنبًا لنواهيه\n◇ثالثا:\nالفتن لما تنتشر بتنشغل بها القلوب، فإذا تعبّد ساعتها إنسان فده بيدل على إن قلبه منشغل بالله أكثر، وإن مكانة ربنا في قلبه أعظم، فساعتها أجره يكون أكبر.\nفمحدش يستهين بأي عبادة يعملها في زماننا دلوقتي، افتكروا دايما الحديث:\n\" ّالعبادة في الهرج كهجرة إلي\"\n18◇العلامة الثامنة عشر زي ما جاءت في الحديث:\nبيعُ الحُكم، يعني إن الناس تتولى المناصب عن طريق الرشوة، والموضوع ده منتشر جدا في الفترة الأخيرة لحد ما بقى طبيعي عند الناس للأسف\n19◇العلامة التاسعة عشر :\nقطيعة الرحم وده عن طريق الأذى أو ترك الإحسان أو الهجر والإبعاد،\nوالأمثلة في حياتنا كتير لو بصينا حوالينا هنشوفها،\nأنا مش عايز أطول كثير في الشرح لأن علامات الساعة الصغرى كثير، وأنا لو استفضت وجبت أمثلة مش هنخلص\n20◇العلامة العشرين: نَشْواً أو نشئاً يتخذون القرآن مزامير\nيعني ناس بدل ما يقرأوا القرآن للتدبر بقوا يتغنوا بيه بالألحان زي المزمار،\nوده منتشر جدا دلوقتي والقراء بيتعلموا المقامات عشان يقرأوا بيها القرآن،\nأيوة مطلوب مننا تحسين الصوت لكن مش معنى تحسين الصوت القراءة بالألحان،\nفالمذموم هنا إللي بيتغنى وبيخرج الحرف عن وضعه ويزيد وينقص عشان يتوافق مع اللحن،\nوممكن الناس ساعتها تقدم الشخص إللي بيتغنى ده حتى وإن كان أقلهم فقها، لأن غرضهم الوحيد إنهم يستمتعوا بالألحان دي\nفلازم نفرق بين تحسين القراءة وتجميل الصوت والخشوع والحزن وبين إن الإنسان يشابه في قراءته أهل الفسق والأغاني\n21◇العلامة الحادية والعشرين : كثرة الشُّرَط\nودول أعوان الوُلاة، لما الحاكم يبقى سفيه وبيكذب ويظلم ويقتل طبيعي إنه يكون له شرطة تساعده على ظلمه،\nوالشُّرَط دول قال عنهم رسول الله ﷺ:\n\" يخرج رجالٌ من هذه الأمة في آخر الزمان معهم سِياط، كأنها أذناب البقر، يغدون في سخط الله، ويروحون في غضبه\"\nوكلمة شُرط يعني علامة، فاسمهم شُرط لأنهم ميزوا نفسهم بعلامات يتعرفوا بها بين الناس،\nفربنا توعد الناس إللي بيتسلطوا على المسلمين دول بغير حق بالنار،\nقال رسول الله ﷺ:\n\"صِنْفَانِ مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمَا :\n قَوْمٌ مَعَهُمْ سِيَاطٌ كَأَذْنَابِ الْبَقَرِ يَضْرِبُونَ بِهَا النَّاسَ ، وَنِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ ، مُمِيلاَتٌ مَائِلاَتٌ ، رُءُوسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ ، \nلاَ يَدْخُلْنَ الْجَنَّةَ وَلاَ يَجِدْنَ رِيحَهَا ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ كَذَا وَكَذَا \"\nوده هياخدنا للعلامة الثانية والعشرين وهي:\n22◇ظهور النساء الكاسيات العاريات\nومعنى الكاسيات العاريات إن النساء دول لابسين ملابس لكنها ضيقة ومفصلة لأجسادهن فكأنها عارية أو لابسين ملابس خفيفة رقيقة مبينة لأجسامهن والجديد في عصرنا بقى وشايفينه إن النساء بتلبس المقطع ومبينة جسمها\nوالله أعلم بعدين هيبقى الوضع بعد كم سنة هيبقى عامل إزاي\nوبما إن النساء بقوا كاسيات عاريات وبيمشوا في الشوارع بالمنظر ده والرجال بيشوفوهم واحنا اتكلمنا قبل كده عن تأثير النساء على الرجال، فالنتيجة الطبيعية لكده انتشار الزنا، ودي العلامة الثالثة والعشرون.\n23◇انتشار الزنا من العلامات إللي ظهرت بطريقة مرعبة في الفترة الأخيرة، وبقى في مجاهرة بالعلاقات المحرمة إللي المفروض إنها حصلت في السر حتى على مواقع التواصل الاجتماعي والموضوع للأسف بقى عادي جدا عند الناس إلا من رحم الله،\nعارفين، \nالزنا هينتشر وسط الناس لحد ما يوصلوا إنهم يستحلّوه،\nقال رسول الله ﷺ:\n\"ليكونن من أمتي أقوام يستحلُّون الحِرَ والحرير والخمر والمعازف\"\nوالحِرَ يعني الزنا،\nولو أخدتم بالكم في زماننا دلوقتي الشاب له صاحبة والبنت لها صاحب إلا من رحم الله، وبيتفاخروا ويعلنوا ده وسط الناس وتخرج مع صاحبها عادي ويعملوا قصاد الناس ما يفعل الرجل مع زوجته في خلوتهم،\nمع إن زمان كنا نادرا لما نشوف بنت ماشية مع شاب، وبتبقى مكسوفة وحاسة إنها بتعمل حاجة غلط، لكن دلوقتي الآية اتعكست وبقى الطبيعي إن البنات يكون لهن أصحاب شباب، \nتخيلوا بقى إن هييجي يوم الرجل هيزني بالمرأة في الشارع كده علنا عادي ومحدش هيكلمه،\nوهيكون أحسن واحد ساعتها هو إللي هيقول له :\nلو إنك تزني بيها وراء الجدار أحسن!\nمتخيلين إنه مش بينكر الزنا، ده بيقول له ازني بس روح وراء الجدار مش في وسط الشارع،\nوده كلام رسول الله ﷺ، قال:\n\" والذي نفسي بيده لا تفنى هذه الأمة حتى يقوم الرجل إلى المرأة فيفترشها في الطريق فيكون خيارهم يومئذ من يقول لو وَاريتها وراء هذا الحائط\"\nأنا شخصيا لما كنت بسمع الحديث ده زمان كنت بستغرب إزاي ممكن الحال يوصل للدرجة دي، لحد ما شفت الحال إللي وصلنا له وكل ده كان بالتدريج،\nقلت لكم قبل كده في قصص الأنبياء لو تفتكروا إن الشيطان مش بيزهق، هو بيحط البذرة ويفضل يرعاها ومعندوش مشكلة إنه يحصد الزرع بتاعه في الجيل إللي بعده\nربنا يعافينا وما يجعلنا نحن ولا ذرياتنا بذرة أو حصاد\n24◇العلامة الرابعة والعشرون : انتشار المعازف والقِينات،\nالموسيقى حرام لا يجوز الاستماع لها، لكن من علامات الساعة انتشار الموسيقى وآلاتها، والقينات يعني المغنيات واحنا شايفين انتشار المغنيات مش بس في التليفزيون ده على اليوتيوب ومواقع التواصل الاجتماعي،\nوالناس مش بس هتسمع الموسيقى لأ ده هيستحلوها أو خلونا نقول إنهم استحلوها بالفعل، \nفي زماننا دلوقتي ناس كتير للأسف بتستحل الموسيقى، وبيسموها غذاء الروح، ولو حاولنا ننكر ونبين الصح يقولوا إننا بنحرم الحلال، ومش عارفين إنهم هم إللي بيستحلوا الحرام\nالمعازف انتشرت بطريقة رهيبة، في الأفراح والمناسبات وفي كل مكان، مفيش مكان نمشي فيه إلا وبنسمع فيه الأغاني والموسيقى للأسف حتى الأجهزة،\nحواسيب، ساعات، سنترالات، مصاعد، ألعاب أطفال، أجراس البيوت، أدوات تعليمية، وفي الفنادق، والمطاعم، والطائرات، وصالات الانتظار، والحافلات،\nولو حاولنا ننكر بنبقى خايفين من العواقب والمشاكل إللي ممكن تحصل لو أنكرنا،\nلكن للأسف الناس إللي بتسمع الأغاني ومتعمدة تسمعها وبتنشرها وبتساعد على نشرها مش عارفة حديث رسول الله ﷺ: \n\" في هذه الأمة خَسف، ومَسخ، وقَذف ، \nقال رجل من المسلمين: يا رسول الله، ومتى ذلك؟ \nقال: \n\"إذا ظهرت القِينات والمعازف، وشُربت الخمور\"\nخسفٌ بالأرض يعني ربنا يأمر الأرض فتنشق وتبتلع الناس دي، ومسْخ من الهيئة البشرية إلى شكل القرد والخنزير، وقذف بشيء من السماء كالحجارة.\n25◇العلامة الخامسة والعشرون: تقارُب الزمان،\nيعني ﻳﺘﺴﺎﺭﻉ ﺍﻟﺰﻣﺎﻥ ﺑﺴﺒﺐ ﻏﻔﻠﺔ ﺍﻟﻨﺎﺱ، فتصبح ﺍﻟﺴﻨﺔ ﻛﺄﻧﻬﺎ ﺷﻬﺮ، وﺍﻟﺸﻬﺮ ﻛﺄﻧﻪ ﺃﺳﺒﻮﻉ، والأﺳﺒﻮﻉ ﻛﺄﻧﻪ ﻳﻮﻡ، وﺍﻟﻴﻮﻡ ﻛﺄﻧﻪ ﺳﺎﻋﺔ والناس بتنشغل ﻓﻲ ﺍﻟﻮﻗﺖ ده باﻟﻠﺬﺍﺕ ﻭﺍﻟﺸﻬﻮﺍﺕ ﻭﺍﻟﻤﺘﻊ، فتذﻫﺐ ﺍﻟﻠﻴﺎﻟﻲ ﻭالأﻳﺎﻡ ﺑﺴﺮﻋﺔ.\n26◇العلامة السادسة والعشرين: نقصان ﺍﻟﻌﻤﻞ،\nيعني قلة العمل بدين الله وقلة الاستقامة عليه والتقصير فيما أوجب الله من علامات الساعة الصغرى، وده ﻓﻲ ﻋﻤﻮﻡ ﺍﻟﻨﺎﺱ، يعني هيبقى المنتشر وسط الناس التفريط في الاستقامة على دين الله،\nوطبعا ده يوضح حال المسلمين دلوقتي في بعدهم عن الدين \n27◇العلامة السابعة والعشرون: الشّح، في الحديث :ﻭﻳُﻠﻘﻰ ﺍﻟﺸﺢ\nوﺍﻟﺸﺢ ﻫﻮ ﺷﺪﺓ ﺍﻟﺒﺨﻞ، النفوس البشرية طبيعتها البخل، لأن الإنسان بيحب يحتفظ بحاجته وميتنازلش عنها،\nوالشح بيدفع الإنسان للقتل وقطيعة الرحم ويمنعه عن تأدية الحقوق الواجبة عليه،\nلكن بالاستعانة بالله والمجاهدة يقدر إلانسان يتخلص من الشح،\n\"وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ\"\n28◇العلامة الثامنة والعشرون: انتشار الربا،\nقال رسول الله ﷺ: \" بين يدي الساعة يظهر الربا\"\nوالربا منتشر جدا في زماننا، منتشر على الشاشات، والبطاقات، والحسابات، وفي الأعمال، والوظائف، والصفقات، ينتشر كأنه غبار يطير، \nوده يعلمنا إننا قبل ما ندخل في بيع أو شراء أو أي معاملات تجارية يكون عندنا فقه في المعاملات دي،\n وعمر بن الخطاب قال : \n\"لا يَبِع في سوقنا إلا من قد تفقّه في الدين\"\nلأن إللي مش هيعمل كده هيقع في الربا بمزاجه أو غصب عنه، لكن للأسف الناس بتكسل ومعندهاش استعداد تتعلم ومش عايزة تتعلم،\n قال رسول الله ﷺ:\n\"ليأتين على الناس زمان لا يُبالي المرء بما أخذ المال أمن حلال أم من حرام\"\nودلوقتي بقى منتشر على النت تجارات كثيرة عن طريق شركات ومعظمها ربا صريح ومع ذلك تلاقي النساء بتشتغل فيها من غير ما تعرف الحكم الشرعي بتاعها مع العلماء قالوا إن التعاملات مع الشركات دي حرام وإن ده ربا،\nلكن لا حياة لمن تنادي\nربنا يرزقنا من الحلال ولا يطعمنا إلا الحلال الطيب\n29◇العلامة التاسعة والعشرين: زخرفة المساجد، \n\"لا تقوم الساعة حتى يتباهى الناس في المساجد\"\nوعن أبي الدرداء قال : \n\" إذا زوّقتم مساجدكم، وحلّيتم مصاحفكم، فالدمار ‏عليكم\"\nوإللي يشوف المساجد دلوقتي هيلاقي فعلا الآية دي تحققت والناس بقى همها زخرفة المساجد أكثر من الصلاة نفسها.\n30◇العلامة الثلاثون : فتح القسطنطينية، إللي هي تركيا حاليا،\nسُئل رسول الله ﷺ: \n\"أي المدينتين تُفتح أولاً قسطنطينية أو رومية، فقال رسول الله ﷺ: مدينة هِرَقل تُفتح أولاً\"\nوتم فتح القسطنطينية على يد محمد الفاتح سنة ثمانمائة وسبعة وخمسون من الهجرة،\nطبعا فتح القسطنيطنية ده له قصة رائعة أتمنى أحكيها لكم في يوم من الأيام إن شاء الله \n☆ملحوظة، مدينة القسطنيطنية أو تركيا هتُفتح مرة ثانية في آخر الزمان وهنتكلم عنها لما نيجي لوقتها\nكل العلامات الثلاثين إللي قلناهم لحد دلوقتي حصلت فعلا، واحنا لما نشوف علامات الساعة إللي تحققت ده يخلي إيماننا بالله وبرسوله يزيد ولو في قلوبنا أي شك لا سمح الله يزول لأننا شايفين العلامات بتحقق\n\"هَذَا مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ وَصَدَقَ اللَّهُ وَرَسُولُهُ وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا\"\nإن شاء الله نكمل المرة الجاية علامات الساعة الصغرى"}, {"n": 143, "l": "الجزء 117 | علامات الساعة الصغرى الجزء الرابع", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_عشر\n#علامات_الساعة_الصغرى\n#الجزء_الرابع\nنكمل باقي علامات الساعة الصغرى،\n31◇ العلامات الواحدة والثلاثون : قتال التُّرك، \nقال رسول الله ﷺ: \n\"لا تقوم الساعة حتى تقاتلوا التُّرك، صِغار الأعْيُن، حُمْر الوجوه،\nذُلْفُ الأنوف كأن وجوههم المَجَان المُطَرّقة، ولا تقوم الساعة حتى تقاتلوا قوما نِعالهم الشعر\"\nوالتّرك غير الأتراك إللي في زمننا دلوقتي، وشكلهم زي ما رسول الله ﷺ وصف، عينيهم ضيقة ووجوههم حمراء وأنوفهم صغيرة وغليظة، \nووجوههم مبطّطة وعريضة زي التِّرس إللي طُرق عليه بالحديد، والأوصاف دي تنطبق على التتار أو المغول، \nوكانوا بيلبسوا في أقدامهم أحذية من الشعر،\nوالتتار أو التُّرك قاتلهم المسلمون فعلا في معركة عين جالوت وانتصروا عليهم سنة ستمائة وثمانية وخمسون658 للهجرة ،\nوبعد ما تركوا بلاد المسلمين، لم يطاردهم المسلمون بعدها لأن رسول الله ﷺ قال:\n\" دَعُوا الْحَبَشَةَ مَا وَدَعُوكُمْ وَاتْرُكُوا التُّرْكَ مَا تَرَكُوكُمْ\"\nيعني ما دام الناس دي سايبينكم في حالكم ولم يعتدوا عليكم متروحوش أرضهم وتبدأوهم انتم بالقتال أو تستفزوهم للقتال،\nلأن الحبشة أو أثيوبيا في زماننا دلوقتي أرضها وَعِرة وهيبقى صعب على المسلمين القتال فيها،\nوالتُّرك بلادهم باردة وجُند المسلمين كانوا من البلاد الحارة فهيبقى في مشقة جامدة عليهم لو حاربوهم،\nده غير إن التُّرك بَأسهم شديد وقوتهم كبيرة وحقدهم شديد على المسلمين، فعدم استفزازهم والبعد عنهم أَوْلى،\nلكن لو الحبشة أوالترك اعتدوا على بلاد الإسلام فيجب على المسلمين القتال والدفاع عن أنفسهم\nالعلماء اختلفوا بقى، هل العلامة دي خلاص كده انتهت بقتال المسلمين للتتار ولّا العلامة دي مُمْتدة وهيكون في قتال تاني قرب الساعة\nفي فريق من العلماء قالوا إن خلاص العلامة دي انتهت، وفريق تاني قال إن قريب من الساعة هيحصل قتال بين المسلمين وبين الترك مرة ثانية،\nلأن رسول الله ﷺ قال في حديث تاني:\n\" تقاتلون بين يدي السَّاعَة قوماً نعالهم الشعر، كأن وجوههم المجان المطرقة، حُمْر الوجوه، صغار الأعين\"\nفاستدلوا من الحديث ده إن في معركة تانية هتحصل بين المسلمين والترك قريب الساعة والله أعلم.\n32◇العلامة الثانية والثلاثون: توقّف الجزية والخِرَاج،\nالجزية هي المال إللي بيدفعه الكفار للمسلمين لأنهم لم يدخلوا في الإسلام؛ في مقابل الدفاع عنهم،\nوالخِرَاج يعني الإيجار إللي بيدفعه إللي بيستفيد من الأراضي الإسلامية بصفة عامة،\nوالجزية والخراج كانوا من أهم مصادر المال لبيت مال المسلمين،\nفرسول الله ﷺ قال إن بعد ما المسلمين هيقعدوا زمن يحصّلوا الجزية والخراج هييجي يوم وهيتوقف المال ده  بسبب استيلاء الكفار على ديار المسلمين في زمن معين،\nإللي هو زماننا واحنا شايفين في عصرنا إزاي احتل الكُفَّار ديار الإسلام، وأَذهبوا دولة الخلافة الإسلامية، وأبعدوا الشريعة الإسلامية عن الحكم، \nومش بس مبقوش يدفعوا الجزية ده كمان بقوا يأخذوا هم الأموال من المسلمين\n33◇العلامة الثالثة والثلاثون : السلام على الخاصة،\nيعني الواحد ميسلمش غير على إللي يعرفه فقط،\nقال رسول الله ﷺ:\n\"إنَّ بَيْنَ يَدَيْ السَّاعَةِ:\n تَسْلِيمَ الْخَاصَّةِ، وَفُشُوَّ التِّجَارَةِ، حَتَّى تُعِينَ الْمَرْأَةُ زَوْجَهَا عَلَى التِّجَارَةِ، وَقَطْعَ الْأَرْحَامِ، وَشَهَادَةَ الزُّورِ، وَكِتْمَانَ شَهَادَةِ الْحَقِّ، وَظُهُورَ الْقَلَمِ\"\nمع إن رسول الله ﷺ قال :\n\"تقرأ السلام على مَن عرفت ومَن لم تعرف\"\nوالصفة دي من خير صفات الإسلام إللي وصى بها رسول الله ﷺ، وده حاصل في زماننا دلوقتي إلا نادرا، المسلمين يمشوا  جنب بعض ومحدش يسلم على التاني،\nلكن الصح إن المسلم إذا قابل حد يسلم عليه سواء كان  يعرفه أو ميعرفوش\n34◇العلامة الرابعة والثلاثون زي ما رسول الله ﷺ قال في الحديث: فُشُوّ التجارة حتى تعين المرأة زوجها على التجارة،\nيعني انتشار التجارة بين الناس لدرجة إن المرأة هتساعد زوجها في تجارته، \nفي نساء مثلا تدخل مع زوجها بنسبة أو بمشاركة أو تدير له جزءاً من العمل، أو يفتح باسمها سجلاً تجارياً؛ لأنه موظف لا يستطيع فتح سجلاً قانونياً وهكذا،\nاحنا ممكن نكون شايفين الموضوع عادي لأنه منتشر جدا بقاله فترة، لكن انتشار التجارة وإعانة المرأة لزوجها على التجارة من علامات الساعة الصغرى،\nوالتجارة مش حاجة وحشة ولا إن المرأة تساعد زوجها ده حاجة وحشة،\nالمذموم هنا إن تكون التجارة هي الشغل الشاغل للرجل والمرأة وميهمهش التجارة دي حلال ولّا حرام،\nواحنا اتكلمنا المرة إللي فاتت عن الزمن إللي هييجي والناس مش هتُبالي هل المال إللي بيحصلوا عليه حلال ولّا حرام،\nوده واضح جدا في زماننا دلوقتي،\nالتجارة منتشرة في كل مكان حتى على الإنترنت والنساء نفسها إما بتشتغل في التجارة أو بتساعد زوجها في تجارته\n☆احنا اتكلمنا عن علامة قطع الأرحام المرة إللي فاتت،\nفهناخد العلامة إللي بعد كده.\n35◇العلامة الخامسة والثلاثون: شهادة الزور وكتمان شهادة الحق،\nوبرده العلامة دي منتشرة جدا دلوقتي، ومش لازم على فكرة شهادة الزور تكون في المحكمة وبس، مع إن شهادة الزور في المحاكم منتشرة بطريقة رهيبة وبصور مختلفة، وللأسف الناس شايفين الموضوع عادي،\nطبعا مش بتكلم من فراغ وإللي شغالين في المحاكم يعرفوا الكلام ده أكثر مني\nلكن شهادة الزور ممكن تكون في حياتنا اليومية واحنا مش واخدين بالنا، لما واحد يسأل واحد صاحبه على حاجة يستشيره فيها، وصاحبه يكتم عنه الحق عشان مصلحته الشخصية، أو الأقارب بينهم وبين بعض،\nوقيسوا على كده، احنا ممكن نكون بنقع في شهادة الزور وكتمان الحق حتى من غير ما ناخد بالنا للأسف، ربنا يعافينا\n36◇العلامة السادسة والثلاثون: ظهور القلم، \nيعني انتشار الكتابة والكتب والمؤلفات والمجلات، لدرجة إن الواحد ممكن يدخل المكتبة يلاقي موضوع واحد بيتكلم عنه كُتّاب كتير، وطبعا ساعد على انتشار الكتب التَّقدُّم المذهل في وسائل التصوير والطباعة والنشر حتى أصبحت الكتب ميسورة لدى أغلبية الناس،\nوبرده ده مش حاجة مذمومة في حد ذاتها، بالعكس احنا ممكن نستفيد من اختلاف العقليات إللي بتكتب،\nلكن المذموم هو نوعية المؤلفات والكتب والمجلات، هل الكتب بتحارب الدين وبتنشر الفواحش ولّا بتساعد الناس إنهم يقربوا من الدين ويعرفوا عنه أكثر\n37◇العلامة السابعة والثلاثون من علامات الساعة: أن تلد الأَمَة ربتها، يعني الأَمَة تلد سيدتها،\nقال رسول الله ﷺ لما سئل عن علامات الساعة:\n\"أن تلد الأَمَة رَبَّتها، وأن ترى الحُفاة العراة العَالَة رُعَاء الشاء يتطاولون في البنيان\"\nوتلد الأمة ربتها لها أكثر من معنى من المعاني دي:\n ◇إن الفتوحات الإسلامية هتكثر وبالتالي هيكون في سراري يتسرى بها الرجل، يعني هيكون عنده ملك يمين، واحنا قلنا إن ملك اليمين زيها زي الزوجة من ناحية المعاشرة،\nفلما يتسرى الرجل بالأمة وتلد له بنت البنت هتكون حرة وهتبقى سيدة أمها.\n◇أما المعنى الثاني هو أن يكثر العقوق في الأولاد، فيعامل الولد أمه معاملة السيد أمته من الإهانة بالسب والضرب والاستخدام،\nتلاقي الشاب أو البنت قاعدين وأمهم هي إللي بتخدمهم ويأمروها وممكن يزعقوا فيها زي ما السيد بيعمل مع أَمَته.\nوالمعنى الثاني هو الأقرب؛\nلأن الكلام عن علامات الساعة بيدل على الحاجات المستغربة إللي هتحصل، وموضوع الجهاد وملك اليمين كان موجود أصلا من عهد رسول الله ﷺ، \nفالأحداث الغريبة إللي ممكن تحصل أن تنعكس الآية، \nوهي بدل ما الأبناء همّ إللي يراعوا الآباء ويخدموهم بقى الآباء هم إللي بيخدموا أبناءهم مع إنهم بقى سنهم كبير ويعتمدوا على نفسهم،\nونظرة على الواقع حوالينا هتشوفوا العلامة دي واضحة جدا\n38◇العلامة الثامنة والثلاثون : التطاول في البُنْيان زي ما جاء في الحديث إللي قلناه من شوية:\n\"وأن ترى الحفاة العُراة العالة رعاء الشاء يتطاولون في البنيان\"\nوالحفاة العراة رعاء الشاة هم العرب، العرب كانوا فقراء جدا وكانوا بيعيشوا في الصحراء والخيام وبيرعوا الغنم،\nفرسول الله ﷺ أخبر إن العرب حالهم هيتغير وهيبنوا البيوت العالية، زي العمارات الكبيرة وناطحات السحاب،\n☆وهنا في معلومة،\nوهي إن التطاول في البنيان في حد ذاته برده مش حاجة مذمومة، لأنه بيحل أزمة سكانية،\nلكن الذم والمشكلة هو التباهي والتنافس في البنيان والزخرفة،\nيعني يكون الهدف من البناء هو التباهي والتفاخر، تلاقي واحد بنى عمارة أو برج وزخرفها يقوم التاني ييجي يبني واحدة أعلى وأكبر وأكثر زينة،\nفهنا التطاول في البنيان بقى مذموم، لكن لو لم يترتب على التطاول في البنيان طغيان، أو بَطَر، أو تفاخُر، أو إسراف، أو إضاعة للحقوق فمفيش مشكلة من بناء العمارات\n39◇العلامة التاسعة والثلاثون : كثرة الزلازل \nوالزلازل من الآيات التي يخوف الله بها عباده عشان يتوبوا ويرجعوا له،\nوحصلت زلازل كثيرة على مر التاريخ من زمن الصحابة لحد زماننا دلوقتي،\nوكل ما المعاصي تزيد ونقرب من يوم القيامة تكثر الزلازل، وفي آخر الزمان الزلازل هتعم الأرض وهتبقى مستمرة ووراء بعضها.\n40◇العلامة الأربعون : تقارب الأسواق، وده معناه إن الأسواق تكون قريبة جدا من بعضها سواء على أرض الواقع أو حتى من خلال الانترنت،\nولو لاحظتم في الفترة الأخيرة هنلاقي مول فتح في مكان وجنبه على طول او قريب منه مول تاني\nحتى أنا نفسي كنت استغرب إزاي مول يفتح جنب مول تاني الفرق بينهم مجرد دقائق مشي\nفانتشار الأسواق بالطريقة دي من علامات الساعة الصغرى،\nواحنا لازم ننتبه كل ما نشوف علامة من علامات الساعة عشان نستعد ونفكر نفسنا دايما إن الدنيا هتفنى في يوم من الأيام وهنقابل في النهاية الإله الخالق وساعتها مش هينفعنا غير عملنا\n41◇العلامة الواحدة والأربعون: غربة الإسلام\nقال رسول الله ﷺ:\n\"بدأ الإسلام غريبا وسيعود غريبا كما بدأ فطوبى للغرباء\"\nومعنى غربة الإسلام إن الإسلام بدأ في أفراد من الناس وقلة قليلة، ثم انتشر فظهر، \nوبعدين سيلحقه النقص والاختلال حتى لا يبقى إلا في أفراد وقلة قليلة زي ما بدأ،\nوفي عصرنا شايفين غربة الإسلام وأد إيه المسلمين بقوا مُفرطين في التمسك بيه، والقلة القليلة هي إللي متمسكة بما كان عليه رسول الله ﷺ وأصحابه الكرام، ربنا يجعلنا وإياكم منهم يارب\n42◇العلامة الثانية والأربعون: تداعي الأمم على أمة الإسلام، وطبعا ده نتيجة طبيعية لبعد المسلمين عن الدين وغربة الإسلام،\nقال رسول الله ﷺ:\n\"يوشك الأمم أن تداعى عليكم، كما تداعى الأَكَلة إلى قَصْعتها. فقال قائل: ومِن قلَّةٍ نحن يومئذ؟\nقال: بل أنتم يومئذٍ كثير، ولكنكم غُثاء كغثاء السَّيل،\nولينزعنَّ الله مِن صدور عدوِّكم المهابة منكم\"\nومعنى الكلام إن الأمم المُعادية للمسلمين هيدعو بعضهم بعضًا عشان يعتدوا على المسلمين ويقاتلوهم ويأخذوا خيرات البلاد الإسلامية وأموالهم وأراضيهم،\nزي لما الناس بيكونوا مجتمعين على طعام وكل واحد يدعو التاني ويعزم عليه ويقول له اتفضل كُل،\nوالصحابة استغربوا، عشان كده سألوا رسول الله ﷺ هل السبب في الذل ده إن عدد المسلمين هيكون قليل، لكن رسول الله ﷺ قال لهم بالعكس المسلمين ساعتها هيكونوا كثير،\nلكن ملهمش أي قيمة زي غثاء السيل، ومفيش في قلوب أعداءه أي خوف منهم، وغثاء السيل معناه الوسخ إللي السيل بيحمله لما يجري في الوادي،\nيعني المسلمين في الوقت ده اسم على الفاضي، لقلة شجاعتهم، ولدناءة آمالهم، ولتعلُّقهم بتوافه الأمور،\nونظرة بسيطة على حالنا هتشوفوا التفهاهة إللي الناس وصلت لها،\nوإزاي الأمم متسلطة على أمة الإسلام وبتذل فيها\nوطبعا لأن ده بقى الحال فالناس كرهت الموت وبقت تحب الدنيا وتعمل لها كأنها هتعيش فيها للأبد ونسيوا إن في حاجة اسمها موت عشان كده وصلنا لحالة الذل إللي احنا فيها دلوقتي،\n\"وليقذفنَّ الله في قلوبكم الوَهَن. فقال قائل: يا رسول الله، وما الوَهْن؟ قال: حبُّ الدُّنيا، وكراهية الموت\"\nوالذل والهوان ده مش هيترفع عن الأمة إلا لما ترجع إلى دينها،\n\"سَلَّطَ اللَّهُ عَلَيْكُمْ ذُلًّا لَا يَنْزِعُهُ حَتَّى تَرْجِعُوا إِلَى دِينِكُمْ\"\nفأي طريق تاني غير العودة إلى الدين مش هينفع\nعارفين ليه \nلأن ببساطة ده الاتفاق بين الله وبين رسول الله ﷺ،\nقال رسول الله ﷺ:\n\"إنِّي سأَلْتُ ربِّي لِأُمَّتي ألَّا يُهلِكَها بسَنةٍ عامَّةٍ وألَّا يُسلِّطَ عليهم عدوًّا مِن سوى أنفسِهم فيَستبيحَ بَيْضَتَهم فإنَّ ربِّي قال :\nيا مُحمَّدُ إنِّي إذا قضَيْتُ قضاءً فإنَّه لا يُرَدُّ وإنِّي أُعطيكَ لِأُمَّتِكَ ألَّا أُهلِكَهم بسَنةٍ عامَّةٍ وألَّا أُسلِّطَ عليهم عدوًّا مِن سوى أنفسِهم فيستبيحَ بَيْضَتَهم ولوِ اجتَمَع عليهم مِن أقطارِها أو قال :\nمَنْ بَيْنَ أقطارِها حتَّى يكونَ بعضُهم يُهلِكُ بعضًا ويَسبي بعضُهم بعضًا\"\nيعني أمة الإسلام لن تهلك بسبب قحط أو مجاعة، ولن تهلك حتى لو اجتمع عليها أعدائها من كل أهل الأرض، \nلكن الحاجة الوحيدة إللي ممكن تهلكهم هم أنفسهم، ببعدهم عن الدين هيعيشوا في ذل وهوان يقتل بعضهم بعضا ويهلكوا أنفسهم\nوده هياخدنا للعلامة الثالثة والأربعين:\n43◇ وقوع التناكر بين الناس،\nقال رسول الله ﷺ:\n\"يُلقى بين الناس التناكر فلا يكاد أحد أن يعرف أحدا\".\nالتناكر بين الناس ده هيكون عند كثرة الفتن والمِحَن وكثرة القتل بين الناس، ولما المادة تستولي على الناس وكل واحد ميفكرش غير في نفسه وفي مصلحته وميهموش مصالح الناس ولا يهتم بحقوقهم فتنتشر الأنانية ويعيش الإنسان وهمه كله أهواءه وشهواته،\nومتبقاش في قيم أخلاقية يرجع لها الناس في التعامل بينهم، \nوبرده للأسف واقعنا وصل للمرحلة دي، بس تقدروا تقولوا إننا لسه في البدايات والجاي أسوأ\n44◇العلامة الرابعة والأربعون : ظهور الفُحش والتفاحش\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى يظهر الفحش والتفاحش\"\nوالفحش معناه كل ما يُشتَد قبحه من الذنوب والمعاصي قولاً أو فعلاً.\nالتفاحش: هو تبادل الفحش أو إظهاره.\nعارفين زي إيه ومنتشر جدا دلوقتي\nالألفاظ البذيئة المبتذلة إللي بنسمعها في كل مكان حتى على مواقع التواصل حتى من البنات والأطفال، وكأن في تنافس بين الناس مين إللي يتفحّش في الألفاظ أكثر ولا حول ولا قوة إلا بالله \n 45◇العلامة الخامسة والأربعون : تشبُّب المشيخة\nيعني ادعاء شيوخ كبار في السن إنهم شباب صغير، وده عن طريق التدليس بإنهم يصبغوا شعرهم بالسواد،\nأو يعملوا عمليات تجميل وشد البشرة وغيرها،\nقال رسول الله ﷺ:\n\"يكون قوم يخضبون في آخر الزمان بالسواد كحواصل الحمام لا يريحون رائحة الجنة\"\nيعني في آخر الزمان الرجال والنساء هيغيروا لون شعرهم الأبيض للون الأسود وده لا يجوز،\nوالصبغ بالأسود حاصل في زماننا دلوقتي\nعلامات الساعة الصغرى كثيرة، فإن شاء الله نكمل المرة الجاية"}, {"n": 144, "l": "الجزء 118 | علامات الساعة الصغرى الجزء الخامس", "u": "", "t": "من علامات الساعه سوء الجوار \n يعني لما تلاقي جارك بيئذيك بقي سواء عمل وشعوذه او سماع اغاني ومعلينها ع اخر ومش بيحترمك اعرف انها من علامات الساعه \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_عشر\n#علامات_الساعة_الصغرى\n#الجزء_الخامس\nاتكلمنا لحد دلوقتي عن خمسة وأربعين علامة من علامات الساعة الصغرى وكلهم اتحققوا وفي منهم إللي مستمر ولسه هيزيد مع الوقت،\nنكمل باقي العلامات،\n46◇العلامة السادسة والأربعون: ظهور موت الفجأة\nقال رسول الله ﷺ : \"إن من أمارات الساعة أن يظهر موت الفجأة\"\nوموت الفجأة معناه إن الإنسان يكون بصحته ولا يشكو من أي مرض وفجأة وبدون سابق إنذار يقع ميت،\nواحنا شايفين فعلا في واقعنا إزاي موت الفجأة منتشر، \nكثرت السكتات القلبية والجلطات والسكتات الدماغية،\nده غير حوادث السيارات،\nواحد يكون راكب عربية رايح مشوار وفجأة يعمل حادثة ويموت، \nناس رايحين يصيفوا فجأة يغرقوا ويموتوا، وأمثلة كثيرة على موت الفجأة وخصوصا الفترة إللي فاتت ولسه هتزيد،\nوخطورة موت الفجأة إن الواحد مش بيبقى عارف آخرته إيه ولا إيه آخر حاجة ممكن يكون هيعملها،\nبعكس لو الإنسان مرض، مرضه ده بيخليه ينكسر لله ويفتكر نهايته فيبدأ يستعد للقاء الله،\nربنا يُعيذنا وإياكم من موت الفجأة\n47◇العلامة السابعة والأربعون : التماس العلم من الأصاغر\nقال رسول الله ﷺ:\n\" إن من أشراط الساعة أن يُلتمس العلم عند الأصَاغِر \"\nوالأصاغر هنا مش معناها إن العالم يكون صغير السن، \nبالعكس ده ممكن يكون صغير في السن وهو نابغة وصاحب همة،\nلكن المقصود بالأصاغر الجهلة إللي بيقولوا برأيهم ومعندهمش علم، يبقى الواحد منهم متعلمش أصلا ولا ترسّخ في العلم ومُتصدر الناس وهم مفكرينه صاحب علم والناس بتاخد منه العلم وهو أصلا جاهل ميفرقش عنهم حاجة إلا شيء بسيط فقط،\nوانتم شايفين النوعيات دي مالية الفيس بكميات رهيبة إزاي، \nكل واحد بيقول برأيه والناس ماشية وراه ومتابعين بالآلاف،\nوفي معنى تاني للأصاغر وهو أهل البدع،\nطبعا العلامة دي غير علامة انتشار الجهل ورفع العلم إللي اتكلمنا عنها في الجزء الخامس عشر\n48◇العلامة الثامنة والأربعون : اتخاذ المساجد طُرقاً\nقال رسول الله ﷺ:\n\" إن من أشراط الساعة: أن يمرّ الرجل بالمسجد لا يصلي فيه ركعتين\"\nوقال: \" من اقتراب الساعة أن تُتّخذ المساجد طرقاً\"\nيعني المساجد هتكون مهجورة والرجل يعدي على المسجد وميصليش فيه، ومساجد الناس هيدخلوها مش عشان الصلاة لكن عشان السياحة والتقاط الصور لأنه متحف أو شيء أثري زي ما بيحصل في بعض البلدان في حاضرنا،\nوفي مساجد الناس هيتخذوها طرق،\nيعني الناس يدخلوا المسجد من باب ويخرجوا من بابه التاني عشان فقط يختصروا الطريق مش عشان يصلوا فيه أو يحضروا مجلس من مجالس العلم.\n49◇العلامة التاسعة والأربعون : انتشار الكذب\nقال رسول الله ﷺ:\n\" سيكون في آخر أمتي أُناس يحدثونكم ما لم تسمعوا أنتم ولا آباؤكم، فإياكم وإياهم\"\nوده يشمل الكذب على رسول الله ﷺ بنقل أحاديث عنه لم يقلها والناس تنشرها بدون ما يتأكدوا من صحتها وانتم شايفين الموضوع ده منتشر أد إيه على رسائل الماسنجر والواتس بالذات\nوبرده الكذب في الكلام عموما سواء في النكت أو نقل الأخبار أو الكلام اليومي بين الناس،\nوطبعا ساعد على انتشار الكذب شبكات التواصل الاجتماعي،\nبقى الواحد يكذب الكذبة فتبلغ الآفاق شرقا وغربا\n50◇العلامة الخمسون: تمني الموت لشدة البلاء.\nقال رسول الله ﷺ:\n\" لا تقوم الساعة حتى يمر الرجل بقبر الرجل فيقول: يا ليتني مكانه\"\nيعني الإنسان هييجي عليه يوم يتمنى الموت بسبب كثرة الفتن وغلبة الباطل وأهله وظهور المعاصي والمنكرات،\nفتمنيه الموت ساعتها لأنه خايف على نفسه من الانحراف وضياع دينه من كثرة الفتن وخصوصا لما يشوف ناس قعدت سنين ملتزمة بدين الله وفجأة تترك الالتزام وتقع في المعاصي جهارا نهارا،\nفهيبقى بالنسبة له إنه يموت دلوقتي أحسن وهو لسه متمسك بدينه ويلقى الله على التمسك ده أحسن ما يعيش يوم زيادة ويقع في الفتنة،\nربنا يثبت قلوبنا على دينه ويحفظنا من الفتن ما ظهر منها وما بطن\n☆ممكن هنا نسأل سؤال، رسول الله ﷺ قال:\n\"لا يَتَمَنَّيَنَّ أَحَدُكُمْ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ\"\nوفي الحديث إللي قلناه من شوية إن هييجي وقت والمؤمن يتمنى الموت ومفيش نهي عن كده، إزاي نوفق بين الحديثين\nالضر أو الابتلاء المقصود في الحديث هو الضرر أو الابتلاء الدنيوي، يعني واحد جاله مرض، أو ربنا ابتلاه بمصيبة من المصائب في الدنيا،\nفهنا مينفعش يتمني الموت بسبب الابتلاء الدنيوي،\nأما الحديث التاني بتاع تمني الموت في وقت الفتن وخوف المسلم على نفسه من إنه يفتن في دينه فده جائز،\nولا شك إن موت الإنسان بعيدا عن الفتن أحسن له من إنه يفتن في دينه حتى لو كان عمله قليل\nقال رسول الله ﷺ:\n\"اثْنَتَانِ يَكْرَهُهُمَا ابْنُ آدَمَ : الْمَوْتُ ، وَالْمَوْتُ خَيْرٌ لِلْمُؤْمِنِ مِنْ الْفِتْنَةِ ، وَيَكْرَهُ قِلَّةَ الْمَالِ ، وَقِلَّةُ الْمَالِ أَقَلُّ لِلْحِسَابِ \"\nحتى عمر بن الخطاب رضي الله عنه دعا ربنا إنه يقبض روحه لما خاف على نفسه وقال:\n\"اللَّهُمَّ كَبِرَتْ سِنِّي ، وَضَعُفَتْ قُوَّتِي ، وَانْتَشَرَتْ رَعِيَّتِي ، فَاقْبِضْنِي إِلَيْكَ غَيْرَ مُضَيِّعٍ وَلا مُفَرِّطٍ \"\nفتمنِّي الموت جائز إذا خاف الإنسان على نفسه أن يُفتن في دينه، لكن لا يتمنى الموت بسبب مصيبة أو ابتلاء في الدنيا،\nلأن طول عمر الإنسان في مصلحته لأنه إما هيزيد في عمله الحسن إذا كان محسن، أو إنه يتوب لو عاصي وبعيد عن الدين،\nقال رسول الله ﷺ:\n\" لا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ وَلا يَدْعُ بِهِ مِنْ قَبْلِ أَنْ يَأْتِيَهُ ،\n إِنَّهُ إِذَا مَاتَ أَحَدُكُمْ انْقَطَعَ عَمَلُهُ ، وَإِنَّهُ لا يَزِيدُ الْمُؤْمِنَ عُمْرُهُ إِلا خَيْرًا\"\nفالأصل عدم تمني الموت إلا لو الإنسان خاف على نفسه من الفتنة في دينه\n51◇العلامة الواحدة والخمسون : ظهور الشرك\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى تلحق قبائل من أمتي بالمشركين، وحتى تعبد قبائل من أمتي الأوثان \"\nوده حاصل في الأمة دلوقتي، بعض الناس مُتبعين للمشركين وعقائد الأمم البعيدة عن الحق، واعتنقوا مذاهبهم الكافرة وأفكارهم الضالة وبيأيدوهم وبينشروا أفكارهم،\nزي مثلا بعض قبائل العرب إللي دخلوا في دين الرافضة في فارس والعراق،\nده غير بقى إللي بيطوفوا حول الأضرحة والقبور بحجة إنها قبور لأولياء صالحين وبيدعوهم ويستغيثوا بهم ويذبحوا لهم الذبائح وهؤلاء أموات لا يملكون حتى لأنفسهم ضرا ولا نفعا\nومن المظاهر العظيمة للشرك عدم تحكيم شريعة الله، وتحكيم القوانين الوضعية، \nوبرده من مظاهر الشرك ظهور الفرق الكفرية إللي انحرفت عن الإسلام وكذبوا بالقدر وبالشفاعة والحوض، وكل ده حاصل في زماننا،\nومش معنى إن ظهور الشرك من علامات الساعة إننا خلاص نستسلم ونسكت\nلأ، يجب علينا إننا ندعو الناس ونعرفهم الصح ونبين لهم الحق من الباطل عشان نرجعهم للإسلام الصحيح وطبعا منكنش منهم\n52◇العلامة الثانية والخمسون: شرب الخمر\nقال رسول الله ﷺ:\n\" من أشراط الساعة أن تُشرب الخمر\"\nوالمقصود هو كل شيء يُذهب العقل، سواء الخمر المعروف من العنب والشعير وغيره، أو ما يدخل في معنى الخمر زي المخدرات من حشيش وأفيون وكوكايين وغيرهم،\nوالمخدرات حكمها حكم شارب الخمر يعني يُجلد شارب المخدرات زي شارب الخمر ثمانين جلدة،\nودلوقتي المسكرات وخصوصا الحشيش بقت منتشرة بطريقة فظيعة لدرجة إنها بقت حاجة عادية،\nوالناس بتبيعها وتشتريها عيني عينك كده عادي جدا\nأما بالنسبة لحكم شارب الخمر في الآخرة ويدخل في حكمه كل مُسكِر فاحنا اتكلمنا عنه بالتفصيل في الجزء التاسع والسبعون في قصة تحريم الخمر ممكن ترجعوا لها لو حبيتم \n53◇العلامة الثالثة والخمسون: سوء الجِوار\nقال رسول الله ﷺ:\n\" لَا تَقُومُ السَّاعَةُ حَتَّى يَظْهَرَ الْفُحْشُ وَالتَّفَاحُشُ، وَقَطِيعَةُ الرَّحِمِ، وَسُوءُ الْمُجَاوَرَةِ\"\nسوء المجاورة في زماننا بقى كبير جدا، مش بس الجار مش بيعرف جاره ولا بيسأل عليه ولا بيساعده،\nلأ ده بقى الجيران بيؤذوا بعض متعمدين،\nواحدة كانت بتشتكي من جارتها إنها بتشغل الأغاني بصوت عالي جدا ولما كلمتها عاندت وعملت معاها مشكلة وبقت تعلي الصوت أكثر وأذيتها أكثر، وخدوا أمثلة من دي كثير\n54◇العلامة الرابعة والخمسون : الخسف والمسخ والقذف\nقال رسول الله ﷺ:\n\" يكون في آخر هذه الأمة خسف ومسخ وقذف، فقالت عائشة رضي الله عنها : يا رسول الله أنهلك وفينا الصالحون؟ قال: نعم إذا ظهر الخبث\"\nوالخسف حصل قبل عصرنا ده ولكنه زاد في عصرنا ولسه هيزيد أكثر كل ما قربنا من الساعة،\n والخسف نذير بين يدي عذاب شديد، وتخويف من الله لعباده، وعقوبة لأهل البدع والمعاصي، عشان يَعتبر الناس ويرجعوا إلى ربهم ويعرفوا إن الساعة قربت،\nلكن المشكلة إن ناس كتير متعرفش الكلام ده وفي ناس عارفة ومستمرة برده في العصيان للأسف،\nوقال رسول الله ﷺ:\n\" ليشربن ناس من أمتي الخمر يُسمونها بغير اسمها، يُعزف على رؤوسهم بالمعازف، يَخسف الله بهم الأرض ويجعل منهم القردة والخنازير\"\nعارفين،\nفي آخر سنة 2018 كان في حفل موسيقي لفرقة شبابية وهم بيغنوا والناس كلهم قاعدين فجأة جاءت موجة تسونامي وبلعت الفرقة بالناس الحاضرين،\nفي ناس ممكن يكونوا شافوا الفيديو وممكن لأ، عامة رابط الفيديو هتلاقوه في التعليقات\nالمشهد مرعب وصريخ الناس يهز القلوب، في لحظة كل حاجة راحت، أظنهم لو كانوا يعرفوا إن دي هتكون نهايتهم مكنش ده هيبقى مكانهم\nوالفيديو ده عينة بس من إللي بيحصل ولسه هيحصل، ربنا يعافينا ويصرف عنا الفتن\n☆ملحوظة :بداية الفيديو فيه موسيقى فياريت توطوا الصوت وانتم بتشوفوا الفيديو\n◇بالنسبة بقى للمسْخ، فالعلماء اختلفوا فيه، \nفي فريق قال إن فعلا الناس ربنا هيمسخها قردة وخنازير على صورة القردة والخنازير زي ما جاء في الحديث بعد ما كانوا بشر، يعني مسخ حقيقي وهو ده القول الراجح،\nوفي فريق تاني من العلماء قال المسخ هنا مسخ معنوي،\nيعني قلوبهم هتبقى زي قلوب القردة والخنازير لا يفرقون بين الحلال والحرام ولا بين المعروف والمنكر،\nوفعلا والله في ناس الواحد بيحس إن قلوبها كده ممسوخة ، لا عارفين يفرقوا بين حلال وحرام ولا بين معروف ومنكر\nعامة سواء كان الخسف صوريا أو معنويا فهو هيحصل هيحصل كما قال رسول الله ﷺ \n55◇العلامة الخامسة والخمسون : ذهاب الصالحين وقلة الأخيار وكثرة الأشرار.\nقال رسول الله ﷺ:\n\"لَا تَقُومُ السَّاعَةُ حَتَّى يَأْخُذَ اللَّهُ شَرِيطَتَهُ مِنْ أَهْلِ الْأَرْضِ ، فَيَبْقَى فِيهَا عَجَاجَةٌ ، لَا يَعْرِفُونَ مَعْرُوفا ، وَلَا يُنْكِرُونَ مُنْكَرًا\"\nيعني الساعة لن تقوم حتى يقبض الله إليه أهل الخير والدين، وميبقاش في الأرض غير الغَوغاء والأراذل ومَن لا خير فيهم\nوقال :\n\" يذهب الصالحون الأول فالأول وتبقى حُثالة كحثالة الشعير والتمر لا يباليهم الله باله\"\nيعني الصالحين هيموتوا الواحد وراء الثاني لحد ما ييجي اليوم إللي مش هيبقى فيه غير حثالة الناس لا يرفع الله لهم قدرا ولا يقيم لهم وزناً،\nوالحديث بيشجعنا إننا نقتدي بالصالحين ونعمل زيهم، ومنخالفش طريقهم وإلا هنكون من الناس إللي ربنا لا يبالي بهم.\n56◇العلامة السادسة والخمسون : صدق رؤيا المؤمن.\nقال رسول الله ﷺ:\n\" إذا اقترب الزمان لم تكد تكذب رؤيا المؤمن\"\nيعني المؤمن صادق الإيمان مجرد ما يشوف رؤيا هيلاقيها تحققت على طول زي ما شافها، يعني مش محتاج حد يفسر له الرؤيا من شدة وضوحها،\nوكل ما كان المؤمن صادق في إيمانه كانت رؤياه صادقة،\nوالحكمة في صدق رؤيا المؤمن إن في الوقت ده المؤمن هيكون غريب وسط الناس البعيدة كل البعد الدين،\nفهيقل أنيس المؤمن ومُعينه على الخير فربنا يكرمه بالرؤيا الصادقة عشان يهوّن عليه غربته.\n57◇العلامة السابعة والخمسون : انتفاخ الأهلّة\nقال رسول الله ﷺ:\n\"من اقتراب الساعة انتفاخ الأهلة، فيرى الهلال لليلة فيقال: لليلتين أو أكثر\"\nوده معناه إن الهلال يكون عمره ليلة لكن إللي يشوفه يفكر إن عمره ليلتين أو ثلاثة.\n58◇العلامة الثامنة والخمسون: قلة الرجال وكثرة النساء\nقال رسول الله ﷺ:\n\" من أشراط الساعة أن تكثر النساء، ويقل الرجال، حتى يكون لخمسين امرأة القيم الواحد\"\nيعني رجل واحد يراعي زوجات وأخوات وبنات عم وخالات وعمات وبنات خال وهكذا، خمسين امرأة ملهمش غير رجل واحد يقوم على مصالحهن،\nوالسبب في كده هيكون كثرة الفتن فبالتالي نسبة القتل هترتفع في الرجال، لأن الرجال هم أهل الحروب مش النساء،\nوسبب ثاني وهو قلة معدل مواليد الذكور يالنسبة للإناث،\nوفي الوقت الحاضر في مائة وثمانية وعشرون دولة يزيد فيها عدد الإناث عن عدد الذكور،\nلكن بصفة عامة على مستوى العالم وعلى حسب الإحصاءات الرسمية فالنسبة بين عدد الذكور والإناث متقاربة،\nلكن هييجي اليوم إللي هيقل فيه عدد الذكور لحد ما يوصل في مقابل خمسين امرأة رجل واحد كما أخبر رسول الله ﷺ \n☆ملحوظة\nعلامات الساعة الصغرى فيها شرح كثير وانا بس بجيب نبذة مختصرة عن كل علامة ومش هينفع أستفيض في الشرح لأن كده هناخد وقت طويل أوي \nفي أحاديث وشروح كثيرة محتاجين نعرفها، هتلاقوا في التعليقات روابط لفيديوهات عن علامات الساعة ياريت لو تسمعوها وكلها من الأحاديث الصحيحة\nإن شاء الله المرة الجاية هيكون الجزء الأخير من علامات الساعة الصغرى وبعدها ندخل في العلامات الكبرى"}, {"n": 145, "l": "الجزء 119 | علامات الساعة الصغرى الجزء السادس", "u": "", "t": "من علامات الساعه زخرفة البيوت والسِمنه واخذ مال مقابل قرائة القرآن ف المياتم \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_عشر\n#علامات_الساعة_الصغرى\n#الجزء_السادس\nوقفنا المرة إللي فاتت عند العلامة الثامنة والخمسون، نكمل في التاسعة والخمسون،\n59◇العلامة التاسعة والخمسون : اقتتال فئتين عظيمتين من المسلمين،\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى تَقْتَتل فئتان عظيمتان، وتكون بينهما مقتلة عظيمة، ودعواهما واحدة\"\nوالعلامة دي حصلت في أيام الصحابة، والفئتين العظيمتين إللي اقتتلوا كانتا فئة علي رضي الله عنه وفئة معاوية بن أبي سفيان رضي الله عنه،\nوالقتال ده كان بعد مقتل عثمان رضي الله عنه، وكان رأي علي رضي الله عنه إن لازم تتم البيعة الأول وتستقر الأوضاع  وبعدين يقتص من قتلة عثمان رضي الله عنه،\nأما معاوية رضي الله عنه فكان عايز يقتص من قتلة عثمان الأول لأن معاوية هو ولي الدم ومن حقه يطالب بالقصاص من قتلة عثمان رضي الله عنه،\nوكانوا خلاص اتفقوا على حل يرضي الطرفين وانتهى الخلاف، \nلكن واحد اسمه عبد الله بن سبأ اليهودي كان أظهر الإسلام عشان يثير الفتن بين المسلمين هو ومجموعة معاه من المنافقين معجبهمش الصلح إللي حصل بين علي ومعاوية رضي الله عنهما وعرف إن مادام حصل بينهم صلح يبقى مسألة وقت لحد ما يفضوا لهم ويقضوا عليهم،\nففي نفس الليلة إللي حصل فيها الصلح قسموا نفسهم نصين جزء راح في جيش علي وجزء راح في جيش معاوية،\nوبدأت كل مجموعة تعتدي على جزء من الجيش وهم نايمين،\nفعلي رضي الله عنه وجيشه ظنوا إن معاوية رضي الله عنه وجيشه غدر بيهم،\nوفي نفس الوقت معاوية رضي الله عنه وجيشه ظنوا إن علي وجيشه غدروا بيهم وقامت الحرب بين الجيشين وحصل القتال\nطبعا الموضوع له تفاصيل كثيرة لكن ده باختصار قصة قتال  الفئتين العظيمتين من المسلمين.\n60◇العلامة الستون : عودة جزيرة العرب جنات وأنهارا،\nقال رسول الله ﷺ:\n\" لَا تَقُومُ السَّاعَةُ حَتَّى تَعُودَ أَرْضُ الْعَرَبِ مُرُوجًا وَأَنْهَارًا\"\nالحديث ده بيدل على إن جزيرة العرب كانت في يوم من الأيام فيها أنهار وكانت أرض خضراء،\nوالإذاعة البريطانية الBBC نشرت في فبراير سنة 2015 تقرير بيقول إن جزيرة العرب كانت جنة خضراء من الغابات والحشائش،\nوعلى حسب التقارير والأبحاث العلمية فإن جزيرة العرب هترجع مرة ثانية في يوم من الأيام مروجا وأنهارا زي ما رسول الله ﷺ أخبر\nوفي مرة وقف رسول الله ﷺ عند أرض تبوك وكان معاه معاذ بن جبل فقال له رسول الله ﷺ:\n\" يوشك يا معاذ إن طالت بك حياة أن ترى ما هاهنا قد مُليء جنانا\"\nوفعلا دلوقتي في أرض تبوك في مزارع كبيرة وضخمة مكنتش موجودة قبل كده ولسه المساحات هتزيد زي ما قال رسول الله ﷺ.\n☆السؤال بقى، إزاي جزيرة العرب اتحولت من أرض مليانة أنهار وخضرة لصحراء جرداء\nجزيرة العرب كانت جزء من قارة أفريقيا وبعدين انفصلت عنها، طبعا الكلام ده قعد ملايين السنين وتغييرات في القشرة الأرضية وحاجات كده لحد ما بقت جزيرة العرب صحراء\nوكل ده بتقدير إلهي حكيم، عشان تكون جزيرة العرب مُمهدة لاستقبال الرسالة الخاتمة، \nلأنها لو فضلت مروج وأنهار فارس والروم مكنوش هيسبوها وكانوا هيحتلوها، \nومهمة رسول الله ﷺ كانت هتبقى أصعب في الدعوة إلى الإسلام لأن فارس والروم كانوا هيحاربوا الإسلام بكل قوتهم،\n وانعزال جزيرة العرب كان سبب في حماية الإسلام من العقائد المنحرفة زي عقيدة الفرس واليونان وغيرها، \nولو تفتكروا في الجزء الحادي عشر اتكلمنا بالتفصيل اشمعنى جزيرة العرب بالذات هي إللي ربنا اختارها عشان تكون فيها رسالة الإسلام فممكن تبقوا ترجعوا للجزء ده،\nوفي التعليقات هتلاقوا رابط لحلقة اسمها لماذا جزيرة العرب، فيها شرح إزاي جزيرة العرب كانت جنات وأنهار وكله بالصور والخرائط،\nبجد حلقة جميلة جدا هتعجبكم إن شاء الله\nوجزيرة العرب هترجع تاني جنات وأنهار سواء عن طريق التدخل البشري في استصلاح الأراضي،\nأو عن طريق المناخ، فالعلماء المشتغلون بالأرصاد والمناخ بيقولوا إن معالم الفترة الجليدية القادمة بدأت،\nوالاحتباس الحراري إللي بسببه الجليد بيذوب هيكون له تأثير على شبه الجزيرة العربية،\nعامة مهما كان السبب فالنتيجة واحدة وهي إن أرض العرب هترجع جنات وأنهار، لكن الموضوع لسه هياخد له وقت\n61◇العلامة الواحدة والستون : كثرة المطر وقلة النبات\nقال رسول الله ﷺ:\n\" لا تقوم الساعة حتى يمطر الناس مطراً عامّاً، ولا تُنبت الأرض شيئاً\"\nوالحديث معناه أن هييجي وقت السماء تمطر مطر كثير لكن ملوش أي فايدة ومفهوش بركة، وبالعكس هيكون فيه الضرر، \nولو لاحظتم في الفترة الأخيرة كل شوية نسمع عن أمطار غزيرة في أماكن مختلفة والأمطار دي تسبب فيضانات وانهيارات أرضية وضرر كبير للناس، \nوكمان في الوقت الحالي المحاصيل الزراعية بقت أقل من الأول وده طبعا أدى لارتفاع أسعار المواد الغذائية،\nفتقريبا والله أعلم دي بداية لعلامة كثرة الأمطار وقلة النبات،\nوهيفضل الوضع كده لحدما تحصل العلامة إللي بعدها وهي:\n62◇العلامة الثانية والستون: توقف نزول المطر\nقال رسول الله ﷺ:\n\" لا تقوم الساعة حتى لا تُمطر السماء، ولا تُنبت الأرض\"\nيعني هييجي يوم مش هيبقى في مطر أصلا وبالتالي مش هيبقى في زرع،\nوالكلام ده هيكون قبل خروج المسيح الدجال بثلاث سنوات،\nالسنة الأولى تَحبِس السماء ثلث المطر، وفي السنة الثانية الثلث الثاني، وفي السنة الثالثة الثلث الثالث، والأرض هي كمان هتحبس ثلث النبات، والثاني، والثالث،\nطبعا هنتكلم عن الموضوع بالتفصيل إن شاء الله لما نيجي نتكلم عن المسيح الدجال،\nوالمسيح الدجال هيخرج في زمن المهدي، والمهدي هيكون حاكم عادل والعدل بييجي معاه كثرة الخير ونزول البركة من السماء،\nلكن الوضع هيتغير قبل خروج الدجال بثلاث سنوات، كل ده هنتكلم عنه بالتفصيل إن شاء الله بس بقول لكم تمهيد بما إننا بنتكلم عن المطر\n63◇العلامة الثالثة والستون : كثرة الروم\nقال رسول الله ﷺ:\n\"تقوم الساعة والروم أكثر الناس \"\nوالروم إللي هم الأوربيون النصارى والأمريكان، والسبب إن الروم هيكونوا أكثر الناس لأن فيهم صفات مش عند غيرهم:\n☆ أَحلمُ النَّاسِ عندَ فِتنةٍ: \nيعني لما تحصل عندهم مشكلة أو فتنة بيفكروا بعقل وبيتثبتوا من الأمور بكل حكمة.\n☆ وأَسرعُهم إفاقةً بعدَ مُصيبةٍ:\nيعني لما تحصل عندهم كارثة أو مصيبة بيعرفوا يحلوها بسرعة ويقدروا يخرجوا منها ويكملوا حياتهم.\n☆ أَوشكُهم كرَّةً بَعدَ فرَّةٍ:\nيعني في الحروب لو انهزموا يرجعوا يقاتلوا مرة واتنين وتلاتة، عندهم طول نفس.\n ☆خَيرُهم لِمِسكينٍ ويَتيمٍ وضعيفٍ\nيعني عندهم التبرعات، وعندهم صدقات، وعندهم كفالة للفقير، والضعيف فيهم، والمسكين.\n☆ أَمنعُهم مِن ظُلمِ المُلوكِ :يعني ملوكهم لا يظلموهم.\nولو لاحظنا هنلاقي إن الروم فعلا فيهم الخصال دي على الرغم من من الكفر والفساد إللي هم فيه لكن عندهم إيجابيات كثيرة، وأهمها العدل وعدم ظلم الناس،\nأيوة أكيد في حالات ظلم لكن بتكون قليلة مش حاكم ولا ملك بيظلم شعب كامل زي ناس\nوطبعا ده ميدخلش في ظلهم وتعديهم على المسلمين، دي قصة تانية خالص، الصفة إللي بنتكلم عنها هي إن ملوك الروم لا يظلمون 《شعوبهم》\nففي آخر الزمان هيقل العرب ويكثر الروم.\n64◇العلامة الرابعة والستون: نقض عُرَى الإسلام\nقال رسول الله ﷺ:\n\" ليُنقضن عرى الإسلام عروة عروة، فكلما انتقضت عروة تشبث الناس بالتي تليها، وأولهن نقضاً: الحكم، وآخرهن الصلاة \"\nوده معناه إن الدين هيفضل ينقص شوية شوية والناس تبدأ تسيب العمل بيه جزء جزء بعد ما كان الدين متكامل،\nوأول حاجة هيتركها الناس الحكم،\nوحصل فعلا، المسلمين دلوقتي بيتحاكموا للقوانين الوضعية، ولو حد فكر إن يطبق الشريعة الإسلامية تُقام عليه الحرب وتُشوّه صورته ويعترض عليه حتى المسلمين أنفسهم،\nوالأحداث في السنوات الأخيرة خير شاهد\nودلوقتي الوضع بين عوام الناس إن كل واحد بياخد من الدين إللي على مزاجه، يلتزم بجزء من الدين ويسيب جزء، \nوهيفضل كده الوضع لحد ما يوصلوا لترك الصلاة بالكلية وده هيكون عام في الأرض في آخر الزمان.\n65◇العلامة الخامسة والستون : زخرفة البيوت\nقال رسول الله ﷺ :\n\"لا تقوم الساعة حتى يبني الناس بيوتاً يُوشُونَها وَشْي المراحيل\"\nوالمراحيل يعني الملابس المنقوشة والمخططة وفيها تصاوير،\nفمن علامات الساعة إن البيوت هتزخرف زي الملابس بالضبط، وطبعا مش محتاجة أقول لكم إن العلامة دي تحققت، \nأكيد شوفتم صور الشقق عاملة إزاي اليومين دول،\nسواء الجدران أو السقوف وكل واحد يتفنن وينافس التاني في الزخرفة وبقى هو ده هم الناس،\nوطبعا السبب في كده هو الانشغال بالدنيا عن الآخرة\n66◇العلامة السادسة والستون: أخذ الأجر على القرآن\nقال رسول الله ﷺ:\n\" سيجيء قوم يقرؤون القرآن يسألون الناس به \"\nيعني الناس إللي بيقعدوا يقرأوا القرآن في العزاء وعلى المقابر والمناسبات في مقابل المال.\n67◇العلامة السابعة والستون : انحسار نهر الفرات عن جبل من ذهب.\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى يُحسَر الفرات عن جبل من ذهب، يقتتل الناس عليه فيُقتل من كل مائة تسعة وتسعون، ويقول كل رجل منهم: لعلي أكون أنا الذي أنجو\"\nوالعلامة دي لسه محصلتش، ومعنى الحديث إن نهر الفرات ماؤه هيقل أو المجرى بتاعه هيتغير وهيظهر من داخله جبل من ذهب،\nوالمقصود بالذهب هو الذهب الأصفر المعروف؛ لأن في ناس غلطوا وقالوا إن الذهب هنا معناه الذهب الأسود إللي هو البترول والكلام ده غير صحيح، لأن البترول لا يكون جبل فوق الأرض،\nالبترول بيستخرج من باطن الأرض، والأصل حمل ألفاظ الشارع على ظاهرها، يعني لما ييجي الشرع بلفظ معين يبقى هو فعلا ده المعنى المقصود، فلما يقول ذهب يبقى هو فعلا الذهب الأصفر،\nوصية رسول الله ﷺ للي يشوف الذهب ده إنه لا يأخذ منه شيء، قال رسول الله ﷺ:\n\" فمن حضره فلا يأخذ منه شيئاً \" \nوعلى فكرة الناس هتبقى عارفة حديث رسول الله ﷺ ومع ذلك هيروحوا يقتتلوا عليه وهيموت من كل مائة تسعة وتسعون إنسان ،وكل واحد بيقول في نفسه لعلي أكون أنا الناجي.\n68◇العلامة الثامنة والستون : كلام السّباع والجماد للإنس\nقال رسول الله ﷺ:\n\"والذي نفسي بيده لا تقوم الساعة حتى يكلم السباع الإنس ويكلم الرجل عَذْبة سوطه وشِراك نعله ويخبره فَخِذَه بما أحدث أهله بعده\"\nوالكلام معناه إن في حيوانات وجمادات هتكلم البشر، وحصل على عهد رسول الله ﷺ إن ذئب كلم راعي غنم، \nوبرده العلامة دي هتحصل تاني في آخر الزمان وطبعا كلام السباع للإنس ده غير دابة الأرض إللي هي من علامات الساعة الكبرى،\nخلونا نشوف قصة الذئب إللي كلم الراعي:\nفي يوم من الأيام كان في راعي بيرعى الغنم فجاء ذئب من الذئاب وأخذ واحدة من الغنم وطلع يجري،\nفالراعي وكان من اليهود طلع يجري وراه لحد ما لحقه وعرف يأخذ منه الغنمة، راح الذئب قاعد على ذيله زي القطط كده لما تقعد على ذيلها وقال الذئب للراعي:\n ّألاَ تَتّقي الله! تنزع مني رزقا ساقه الله إليّ\nفالراعي استغرب جدا وقال :\nيا عجبي ذئب مُقْعَ على ذَنبِه يكلمني كلام الإنس\nيعني ذئب قاعد بيتكلم كلام البشر،\nفراح رادد عليه الذئب وقال له:\nطيب أنا أقولك عن حاجة أعجب من كده؟! محمد ﷺ في يثرب بيخبر الناس بأنباء ما قد سبق!\nفأخذ الراعي الأغنام وراح المدينة ووضع الأغنام في زاوية وانطلق لرسول الله ﷺ في المسجد وأخبره باللي حصل معاه،\nفقام رسول الله ﷺ وأمر أن يُنادى في الناس: الصلاة جامعة!\nفاجتمع الناس فقال رسول الله ﷺ للراعي أخبرهم باللي حصل، فحكى الراعي للناس قصته مع الذئب،\nفقال رسول الله ﷺ بعدها : \"صدق، والذي نفسي بيده لا تقوم الساعة حتى يُكلم السباع الإنس\"\nوشِراك نعله ويخبره فَخِذَه بما أحدث أهله بعده:\nشراك نعله يعني الجزمة إللي بيلبسها،\nوالمعنى إما إن الجمادات تتكلم على الحقيقة، سواء الفخذ أو شراك النعل وتخبر الإنسان أهله عملوا إيه وهو ميعرفش،\nأو معنى تاني وهو إنه يضع كاميرات مراقبة أو تسجيلات صوتية في النعال أو في أي مكان وبعدين الأجهزة دي تعرّفه بالحاجات إللي اهله عملوها من وراه.\n69◇العلامة التاسعة والستون : ظهور الرواحل الجديدة\nقال رسول الله ﷺ:\n\" سَيَكُونُ فِي أُمَّتِي رِجَالٌ يركبون عَلَى سُرُجٍ كَأَشْبَاهِ الرِّحالِ، ينزلون على أبواب المساجد، نساؤهم كَاسِيَاتٍ عَارِيَاتٍ\"\nوكلمة أشباه الرحال يعني مركوبات جديدة لم يرها رسول الله ﷺ، وإللي ياخد باله هيعرف إن المقصود بأشباه الرِّحال هو السيارات،\nوشوفنا فعلا الرجل ينزل من السيارة على باب المسجد للصلاة وزوجته معاه في السيارة كاسية عارية\n70◇العلامة السبعون: كثرة السِّمَن في الناس، وظهور قوم يَشهَدُونَ وَلا يُستَشهَدونَ.\nقال رسول الله ﷺ:\n\" خَيرُ أُمَتِي قَرْني، ثُمَّ الذِينَ يَلونَهُم، ثُمَّ الذينَ يَلونَهُم، \nثُمَّ إنَّ بَعدَهم قَوماً يَشهَدُونَ وَلا يُستَشهَدونَ، وَيَخُونون ولا يُؤتَمَنونَ، ويَنذُرُون ولا يوفُونَ، ويَظهَرُ فيِهم السِّمَنُ\"\nيعني أفضل القرون هم أول ثلاثة قرون من عهد رسول الله ﷺ، \nوبعدين هييجي ناس في آخر الزمان من أوصافهم إنهم يشهدون ولا يستشهدون، يعني هيتساهلوا بالشهادة على الآخرين بغير علم ولا طلب،\nوهيخونوا الأمانة، وهيكثروا في النذر ومحدش فيهم هيوفي بنذره، وده بسبب رقة الدين وضعف الإيمان،\n أما بالنسبة لكثرة السِّمَن فمعناه إن الناس هتكون سمينة، والسمنة فعلا منتشرة جدا في العالم،\nوالسبب في السمنة انتشار الترف وتنوع الأكل والشرب وقلة الحركة بسبب التقدم العلمي والأجهزة الحديثة إللي بتخدم الإنسان في كل المجالات تقريبا\nكده احنا خلصنا الجزء الأول من علامات الساعة الصغرى، \nفي علامات صغرى متداخلة مع العلامات الكبرى، \nزي مثلا خروج المهدي ودي علامة كبرى وفي نفس الوقت هتحصل الهدنة بين الروم والمسلمين ودي علامة صغرى،\nفمن أول الجزء الجاي إن شاء الله هنتكلم عن علامات الساعة الكبرى وهم عشر علامات وفي النص هنقول علامات صغرى متداخلة مع العلامات الكبرى\n☆"}, {"n": 146, "l": "الجزء 120 | علامات الساعة الكبري الجزء الاول | المهدي", "u": "", "t": "من علامات الساعه هاييجي فتره يكون فيها قتال بالرمح والاسهم ومش هايكون ف اي نوع من انواع التواصل الاجتماعي \n#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_مائة_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الأول\n#المهدي\nهنبدأ إن شاء الله نتكلم عن علامات الساعة الكبرى، وعلامات الساعة الكبرى عشر علامات هي:\n1◇خروج المسيح الدجال\n2◇نزول عيسى بن مريم عليه السلام\n3◇خروج يأجوج ومأجوج\n4◇طلوع الشمس من مغربها\n5◇الدخان\n6◇خروج دابة الأرض\n7◇ خسف بالمشرق\n8◇خسف بالمغرب\n9◇خسف بجزيرة العرب\n10◇ نار تخرج من اليمن تطرد الناس إلى محشرهم\nعن حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ رضي الله عنه قَالَ :\nاطَّلَعَ النَّبِيُّ ﷺ عَلَيْنَا وَنَحْنُ نَتَذَاكَرُ فَقَالَ: \nمَا تَذَاكَرُونَ ؟ قَالُوا : نَذْكُرُ السَّاعَةَ ، \nقَالَ : إِنَّهَا لَنْ تَقُومَ حَتَّى تَرَوْنَ قَبْلَهَا عَشْرَ آيَاتٍ فَذَكَرَ الدُّخَانَ وَالدَّجَّالَ وَالدَّابَّةَ وَطُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا وَنُزُولَ عِيسَى ابْنِ مَرْيَمَ ﷺ وَيَأَجُوجَ وَمَأْجُوجَ وَثَلاثَةَ خُسُوفٍ خَسْفٌ بِالْمَشْرِقِ وَخَسْفٌ بِالْمَغْرِبِ وَخَسْفٌ بِجَزِيرَةِ الْعَرَبِ ،\nوَآخِرُ ذَلِكَ نَارٌ تَخْرُجُ مِنْ الْيَمَنِ تَطْرُدُ النَّاسَ إِلَى مَحْشَرِهِمْ .\nدول عشر علامات موجودين في حديث واحد، في علامة تانية من علامات الساعة الكبرى موجودة في أحاديث تانية مختلفة صحيحة وهي ظهور المهدي،\nوالمهدي هو أول علامة من علامات الساعة الكبرى، يعني يعتبر حلقة الوصل بين علامات الساعة الصغرى وعلامات الساعة الكبرى،\nقبل ما نعرف مين هو المهدي وإيه قصته، أنا قلت لكم المرة إللي فاتت إن في علامات ساعة صغرى متداخلة مع علامات الساعة الكبرى، \nمن علامات الساعة الصغرى المتداخلة مع الكبرى علامتين هما : ظهور الجَهْجَاه وظهور القحطاني،\nوالعلامتين دول العلماء مختلفين في وقت ظهورهم، في علماء قالوا إن ظهورهم هيكون بعد زمن المهدي وعيسى،\nوفي فريق تاني قال إن ظهورهم هيكون قبل المهدي،\nلكن مفيش دليل بيؤكد أو بيقول وقت ظهورهم بالضبط، \nكلها اجتهادات العلماء، \nلكن هم أكيد هيظهروا وده إللي يهمنا، فاحنا هنتكلم عنهم قبل ما نتكلم عن المهدي عشان نبقى خلاص خلصناهم وعرفناهم\n1◇الأول : ظهور الجَهْجَاه،\nقال رسول الله ﷺ:\n\" لا يذهب الليل والنهار حتى يملك رجل من الموالي يقال له: الجَهْجَاه\"\nيعني في مَلك هيحكم المسلمين يُقال له الجهجاه،\nوكلمة مَوْلى معناها العبد المُحرر أو الحِليف، فالجهجاه ده إما هو عبد محرر أو من حلفاء المسلمين إللي انضم لهم وبقى عزه من عزهم،\nوده إللي نعرفه عنه فقط، رسول الله ﷺ لم يذكر صفاته ولا امتى هيخرج ولا فترة حكمه أد إيه\n2◇الثاني : خروج القحطاني\nقال رسول الله ﷺ:\n\"لا تقوم الساعة حتى يخرج رجل من قَحْطَان يسوق الناس بعصاه\"\nوالقحطاني ده رجل من الأحرار لأن نسبه إلى قحطان الذي تنتهي إليه أنساب أهل اليمن،\nوهو رجل مسلم صالح يحكم بالعدل، أما جملة يسوق الناس بعصاه فهي بتدل على قوته وسطوته وإنه يحمل الناس على الدين، يعني يَغصبهم على الإلتزام بالدين والناس ستنقاد له زي ما راعي الغنم بيقود الغنم بعصاه، \nوهو شديد ويقسو على أهل المعصية من الناس\nوالقحطاني غير الجهجاه وهو ده القول الصحيح لأن في علماء بيقولوا إن القحطاني والجهجاه رجل واحد.\nنرجع بقى للعلامة الأولى من علامات الساعة الكبرى وهي خروج المهدي،\n◇نسبه:\nالمهدي رجل صالح من ذرية محمد ﷺ من نسل فاطمة بنت رسول الله ﷺ، تحديدا من نسل الحسن بن علي رضي الله.\n◇زمن خروجه:\nالمهدي هيخرج في آخر الزمان في وقت الأرض هتكون امتلات ظلم وعدوان، \nومعنى إنها امتلأت ظلم وعدوان يعني الظلم والعدوان منتشر في كل مكان في الأرض فهو صورة عامة للأرض ساعتها، وهيكون زمن زلازل وفتن،\nودي علامة ظهوره، مش هيخرج غير لما يكون الظلم والعدوان منتشر في كل مكان،\nفلما يخرج ربنا هيصلح بيه أمور الناس ويملأ الأرض عدل وقسط وتكون خلافته على منهاج النبوة.\n◇الاسم:\n اسمه زي اسم رسول الله ﷺ محمد أو أحمد، واسم ابيه زي اسم أبو رسول الله ﷺ،\nفهيكون اسمه محمد بن عبد الله أو أحمد بن عبد الله، ومينفعش يكون اسمه أي اسم تاني،\nوالمهدي نفسه مش هيبقى عارف إن هو نفسه المهدي\nلأن ربنا هيصلحه في ليلة، عشان بس مش كل شوية واحد يطلع ويقول أنا المهدي\nقال رسول الله ﷺ : \" المهدي منا أهل البيت يُصلحه الله في ليلة\"\nيعني ربنا هيتوب عليه ويوفقه لأنه مكنش كده،\nوهيلهمه ويرشده ويهيأه لاستلام الخلافة ، يعني هو زيه زي أي بشر واقع في المعاصي، فهو غير معصوم لأن العصمة للأنبياء فقط وهو مش نبي هو مجرد رجل صالح له دور معين في زمن معين\n◇لقبه:\nاللقب بتاعه: المهدي، ورسول الله ﷺ هو إللي لقبه باللقب ده، \nقال رسول الله ﷺ:\n\"يخرجُ في آخرِ أُمَّتي المهديُّ\"\n☆وهنا في معلومة:\nلقب المهدي ده لم يشترك فيه غير الخلفاء الأربعة أبو بكر وعمر وعثمان وعلي رضي الله عنهم أجمعين،\nقال رسول الله ﷺ:\n\" عليكم بسنَّتي وسنَّةِ الخلفاءِ الراشدينَ 《المهديِّينَ》، عَضُّوا عليها بالنَّواجذِ\"\nوده بيدل على حصول المهدي على الهداية والتوفيق من الله عز وجل\n◇شكل المهدي:\nقال عنه رسول الله ﷺ:\n\" المَهْديُّ منِّي، أجلى الجبهةِ، أقنى الأنفِ\"\nأجلى الجبهة يعني جبهته كبيرة وشعر رأس مُنحسر، يعني زي ما بنقول أقرع من مقدمة رأسه\nوأقنى الأنف معناها: \nأنفه طويلة وأرنبة أنفه صغيرة ..نهاية أنفه يعني، وفي وسط الأنف حَدب يعني في ارتفاع عند قصبة الأنف بدون ما يكون شكلها قبيح، وهي نفس أنف رسول الله ﷺ.\n◇مدة حكمه:\nيحكم في الأرض سبع سنين أو ثمانية، يسقيه الله الغيث، يعني المطر النافع إللي يخرج بسببه النبات، والأرض هتخرج نباتها وتكثر الماشية وتعظم الأمة في عهده،\nويكثر المال لدرجة إنه لما ييجي يعطي واحد المال يُحثِيه حَثْيا، يعني يكبش بإيده ويعطيه،\nفهو مش هيعِد المال ويعطيه للناس لكن هيكبش المال بإيده\n ويعطيه للناس،\nالمكان إللي هيخرج منه المهدي غير معروف، وفي حديث بيقول إنه هيخرج من الشرق من ناحية خُراسان، لكن الحديث ده اختلف عليه العلماء في علماء قالوا إنه حديث حسن وعلماء تانيين ضعّفوه ومنهم الشيخ الألباني،\nفمفيش حديث ثابت بيأكد على مكان خروج المهدي. \n☆ملحوظة : في أحاديث غير صريحة العلماء استنبطوا منها إن الكلام فيها عن المهدي،\nزي الحديث إللي عائشة رضي الله عنها قالته عن رسول الله ﷺ:\n\" قالت: \"عبث رسول الله ﷺ في منامه -يعني اضطرب جسمه وهو نائم-\n فقلنا: يا رسول الله، صنعت شيئًا في منامك لم تكن تفعله؟ فقال: العجب إن ناسًا من أمتي يؤُمُّون بالبيت برجل من قريش قد لجأ بالبيت حتى إذا كانوا بالبيداء خُسف بهم\nفقلنا: يا رسول الله، إن الطريق قد يجمع الناس؟\nقال:\nنعم فيهم المسُتَبصر، والمجبور، وابن السبيل، يهلكون مهلكًا واحدًا، ويَصدرون مصادر شتى، يَبعثهم الله على نياتهم\"\nوالحديث معناه إن في واحد هيهرب ويحتمي بالبيت، لكن في جيش هييجي عشان يغزو مكة ويقاتل الرجل ده،\nفلما يكونوا في وسط الطريق بين مكة والمدينة يخسف الله بهم جميعا،\nفالصحابة قالوا إن الطريق بيجمع الناس، يعني الطريق فيه جيش وفيه إللي خارج للحج أو العمرة وفيه المسافر،\nفكده في ناس هيُخسف بيهم وهم مش تبع الجيش\nفرسول الله ﷺ وضح لهم إن فيهم المُسْتَبصر يعني: \nالمُستَبين العالم العامد بالقضية وإنه ذاهب لغزو مكة،\nوفيهم المجبور: يعني إللي خارج وهو مُكره،\nوفيهم ابن السبيل يعني إللي ماشي معهم في الطريق وليس منهم فرأى جيش فمشى جنبه،\nفدول كلهم ربنا يخسف بهم الأرض ويوم القيامة يُبعثوا على نياتهم، كل واحد كانت نيته إيه،\nفالعلماء قالوا إن العائذ إللي لجأ بالبيت ده هو المهدي،\nوالسبب في إنه هرب للكعبة إن الناس كانوا عايزين يبايعوه على الخلافة لكن هو كان رافض،\nودي علامة صلاحه لأن خائف من مسؤولية حمل الأمانة،\nفحاول إنه يبعد عنها ويزهد فيها لعل ربنا يعينه عليها لو الناس صمموا على مبايعته،\nلأن رسول الله ﷺ قال إن الإمارة حسرة وندامة، فلو حد سأل الإمارة وأخذها بيُوكل إليها وربنا لا يعينه عليها،\nأما إللي بيُعطى الإمارة من غير ما يسألها ده ربنا بيعينه ويوفقه ويسدده ويرشده،\nفالمهدي كان يرجو إن السداد والتوفيق من الله عز وجل.\n♡وهنا في فائدة مهمة وهي:\nالبعد عن أهل الظلم والمعاصي وإن الإنسان ميكنش معاهم في اجتماع ولا في مكان ولا حتى لو مجرد مصاحبة في الطريق؛ لأن لو عقاب ربنا نزل عليهم هيلحقه معهم،\nومثال على كده الأفراح المختلطة والحفلات إللي فيها أغاني ورقص ومعاصي ومنكرات،\nوأنا مش عارفة انتم شوفتم الفيديو بتاع حفلة الفرقة الموسيقية إللي ابتلعها الموج، والحفلة دي كان فيها مسلمين وكان فيها أطفال،\nفالأصل إننا نبعد عن أهل المعاصي والظلمة عشان لا يلحقنا العقاب معهم سواء في الدنيا أو في الآخرة.\nقلنا إن المهدي هيحكم سبع سنين أو ثمانية، خلال السبع سنين دول هتحصل أحداث عظيمة، \nمن الأحداث دي علامة من علامات الساعة الصغرى وهي: 71◇الملاحم،\nوالملاحم هي القتال بين المسلمين والروم من جهة وبين المسلمين واليهود ومعهم الدجال من جهة تانية،\nوالقتال بين المسلمين والروم له مقدمة،\nفاكرين لما قلنا في الحديث :\n\" أُعدُدْ ستًّا بين يدي الساعةِ : \nمَوتي ؛\nثم فتحُ بيتِ المقدسِ ،\nثم مُوتانِ يأخذ فيكم كقُعاصِ الغنمِ ،\nثم استفاضةُ المالِ حتى يُعطَى الرجلُ مائةَ دينارٍ ، فيظلُ ساخطًا ،\nثم فتنةٌ لا يبقى بيتٌ من العربِ إلا دخلَتْه ، \n《ثم هُدنةٌ تكون بينكم وبين بني الأصفرِ ، فيغْدرون ، فيأتونكم تحت ثمانينَ غايةً ، تحت كلِّ غايةٍ اثنا عشرَ ألفًا》\nاحنا اتكلمنا عنهم كلهم ما عدا علامة الهدنة،\nوهي دي بداية الملحمة الكبرى، هيحصل بين المسلمين بين الروم إللي هم النصارى هُدنة أو صُلح،\nوالنصارى من بداية الإسلام وهم بيحاربوا المسلمين على مر العصور من أول عهد رسول الله ﷺ في معركة مؤتة إللي هنتكلم عنها في السيرة لما ييجي وقتها إن شاء الله،\nمرورا بالحملات الصليبية وتحالف النصارى مع التتار لحد اعتداء الروم النصارى على المسلمين في عصرنا الحديث سواء في العراق أو أفغانستان أو غيرها من البلدان،\nفبعد الصراع الطويل ده هيحصل هدنة وصلح يأمن فيها المسلمين على أنفسهم ويأمن فيها الروم على أنفسهم،\nوهيبقى في عدو مشترك للروم و المسلمين،\nفالروم والمسلمين هيتحدوا مع بعض ويعملوا جيش يقاتلوا العدو ده، هل العدو المشترك ده هم التّرك ولّا الصين ولّا الهند ولّا غيرهم؟ الله أعلم\nالمهم إن المسلمين والنصارى هينتصروا على العدو ده وهيغنموا كمان وهيرجعوا سالمين يعني مش هيبقى في قتلى منهم كثير، \nوبعدين يرجعوا لحد ما ينزلوا منطقة اسمها مَرج ذي تُلول،  والمرج معناه أرض واسعة فيها نباتات كثيرة ترعى فيها الدواب، \nوالتلول معناها: كل ما اجتمع من الأرض من رمل أو تراب،\nوالمكان ده قريب من الحدود السورية التركية في زماننا دلوقتي،\nلما الجيش ينزل المكان ده واحد من النصارى هيرفع الصليب ويقول : غلب الصليب، يعني الصليب انتصر،\nفهنا واحد من المسلمين هيغضب ويقوم يأخذ منه الصليب ويكسره ويقول المسلم: بل الله غلب\nفيغدر الروم ويجتمعوا على المسلم فيقتلوه، فهنا يثور المسلمون ويأخذوا سلاحهم ويقاتلوا الكفار،\nلكن الله سبحانه وتعالى يشاء إن المجموعة دي وهي طليعة المسلمين إنهم يُقتلوا كلهم ويكرمهم الله بالشهادة ، ويقول الروم لقائدهم : كفيناك حد العرب وبأسهم!\nيعني خلاص قضينا على العرب، والعرب في الوقت ده هيكون عددهم قليل، لكن المسلمين بصفة عامة عددهم كبير،\nالنصارى هيبدأوا يجمعوا جيش لاكتساح المسلمين والقضاء عليهم،\nويأتوا للمسلمين تحت ثمانين غايو أو راية، كل راية تحتها اثنا عشر ألف مقاتل، يعني جيش الروم هيبقى عدده 960 ألف، يعني قريب من المليون مقاتل من الرومان،\nوالجيش ده هينزل في منطقة اسمها مَرْج دابق، وهي منطقة قريبة من حلب،\nفهيخرج من مدينة حلب أو مدينة دمشق للجيش الروماني جيش من خيار أهل الأرض في الزمن ده،\nفإذا تصافّ الجيشان، يعني وقفوا قصاد بعض قالت الروم:\n\"خلّوا بيننا وبين الذين سُبوا -أو سَبوا- منا، نقاتلهم\"\nيعني جيش المسلمين هيكون فيه روم أسلموا، وانضموا لجيش المسلمين،\nفالروم النصارى بيقولوا للمسلمين احنا عايزين نقاتل أبناء جلدتنا مش عايزين نقاتل غيرهم،\nفالمسلمين هيقولوا لهم:\n\" لا والله لا نُخلي بينكم وبين إخواننا\"\nيعني صحيح إن أصلهم منكم، وأصلهم من الروم لكن لما أسلموا خلاص بقوا إخواننا ولا يمكن نتخلى عنهم، لا يمكن نتركهم ولا نسلمهم إليكم، فيبدأ القتال بين الروم والمسلمين.\n☆ملحوظة:\nالقتال هيكون بالسيوف والرماح والسهام، يعني في الوقت ده مش هيبقى في تكنولوجيا ولا أسلحة آلية،\nهترجع البشرية للعصور القديمة، لكن هترجع إزاي الله أعلم\nلكن متنسوش إن الزلازل هتبقى منتشرة جدا في كل أنحاء الأرض وكذلك البراكين، وأشد أعداء التكنولجيا والمباني الزلازل والبراكين،\nالمباني لن تستقيم وتفضل زي ما هي مع كثرة الزلازل، وفي مرة حصل إن بركان ثار في جزيرة أيسلندا فتعطل الطيران فيها شهر،\nوفي حاجة اسمها الطيف الشمسي لو زاد ولو بنسبة بسيطة كل أجهزة السات لايت في الفضاء الخارجي هتتعطل،\nوممكن تحصل حرب عالمية ثالثة وده احتمال وارد جدا،\nو أكيد الأسلحة في الحرب دي هتبقى الأسلحة المتطورة،\nفتخيلوا لما تحصل الحرب بالأسلحة دي هتكون النتيجة إيه\nده غير إن كل حضارة لها نهاية،\nالفراعنة كان عندهم التحنيط مثلا ومع ذلك احنا منعرفش عنه حاجة، اندثر مع الفراعنة،\nوكذلك عاد وثمود مفيش حاجة باقية من حضارتهم مع إن كان فيهم ناجين مسلمين،\nلكن كل الحضارات السابقة اندثرت وانتهت، ففي زمن المهدي إللي هيكون فيه القتال بالسيوف هتكون فيه الحضارة بتاعتنا انتهت خلاص\nإيه بقى نتيجة الحرب إللي كانت بين المسلمين وبين الروم\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 147, "l": "الجزء 121 | علامات الساعة الكبري الجزء الثاني | حقيقة هرمجدون والملحمه  الكبري | المسيح الدجال الجزء الأول", "u": "", "t": "المسيح الدجال الجزء الأول \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وعشرون\n#علامات_الساعة_الكبرى_الجزء_الثاني\n#حقيقة_هَرْمَجدُّون_والملحمة_الكبرى\n#المسيح_الدجال_الجزء_الأول\nوقفنا المرة إللي فاتت عند القتال إللي حصل بين المسلمين والروم في أكبر معركة بين المسلمين والروم النصارى على مر التاريخ،\nفالمعركة دي أول معركة يقابل فيها جيش من النصارى قريب من المليون،\nوقائد المسلمين ساعتها على حسب شرح العلماء للأحاديث هو المهدي إللي اتكلمنا عنه المرة إللي فاتت،\n☆ملحوظة:\nالشيعة الرافضة عندهم مهدي اسمه محمد العسكري، \nبيقولوا إنه دخل في السرداب من زمان وعايش فيه بقاله سنين طويلة وهيخرج في آخر الزمان من مدينة سامراء وكلام كتير كده ده كله كذب وافتراء ملناش دعوة بيه\nعشان بس محدش يتلغبط بين المهدي الحقيقي إللي أخبر عنه رسول الله ﷺ في الأحاديث الصحيحة وبين المهدي المزعوم إللي الشيعة بيقولوا عليه\nنرجع للمعركة،\nأول ما يبدأ القتال هينهزم ثلث الجيش المسلم، قال عنهم رسول جالله ﷺ:\n\" فينهزم ثلث لا يتوب الله عليه أبداً\"\nالثلث إللي انهزم ده ثلث عاص عمل كبيرة من الكبائر وهي الفرار من الزحف، والثلث ده لن يُقدّر الله لهم توبة ولن يوفّقهم للتوبة،\nأما ثلث الجيش المسلم الثاني فيهقتلهم الروم ويموتوا شهداء في سبيل الله،\nقال عنهم رسول الله ﷺ:\n\" ويُقتل ثلثهم، أفضل الشهداء عند الله\"\nيعني الثلث الثاني إللي هيُقتل ده هم أفضل الشهداء عند الله،\nكده هيتبقى ثلث الجيش المسلم الأخير، والثلث ده هو إللي هينتصر ولن يُفتنوا في دينهم ولن يتركوا دينهم لحد ما يموتوا،\nقال عنهم رسول الله ﷺ:\n\" ويَفتتح الثلث لا يُفتنون أبداً\"\nإيه بقى أحداث المعركة دي وإزاي هينتصر المسلمون على الروم\nمبدئيا مقر جيش المسلمين هيكون في مدينة اسمها الغُوطة إلى جانب مدينة دمشق في مكان البساتين.\n☆ومدينة الغوطة معروفة في سوريا في زماننا دلوقتي وحصل فيها مجازر على يد قوات بشار الأسد ربنا ينتقم منهم جميعا \n \nقال رسول الله ﷺ:\n\"إن فُسطاط المسلمين يوم الملحمة بالغوطة إلى جانب مدينة يُقال لها: دمشق من خير مدائن الشام\"\nأما مكان المعركة هيكون بقرب مدينة حلب في منطقة مرج دابق إللي قلنا عليها المرة إللي فاتت،\nالقتال هيبدأ بين الثلث الباقي من جيش المسلمين وبين جيش الروم،\n\"فيشترطُ المسلمون شُرطَةٌ للموت لا ترجع إلا غالبة\"\nيعني مجموعة من المسلمين هيقولوا لبعض تعالوا نهجم على جيش الروم نقاتلهم، فإما نرجع بعد ما نغلبهم يا إما نموت،\nفيقتتل جيش المسلمين مع جيش الروم لحد ما ييجي الليل فيرجع كل جيش للمعسكر بتاعه من غير ما يكون في طرف منتصر،\nوفي نفس الوقت شرطة الموت هتكون هجمت لكنها هتُقتل جميعا وتفنى في سبيل الله وميتبقاش منهم ولا واحد،\nتاني يوم هيشترط المسلمون شرطة للموت مرة ثانية ويهجم الجيش المسلم على جيش الروم ومعاهم شرطة الموت فيقتتلون،\nوالنتيجة هتكون مقتل شرطة الموت كلها، وبرده هيرجع الجيشان عند الليل من غير ما يكون في طرف منتصر على الثاني\nاليوم الثالث هيحصل نفس الموضوع، يشترط المسلمون شرطة للموت لا ترجع إلا غالبة، فيقتتلون لحد المساء فيرجع الجيشين كل واحد للمعسكر بتاعه من غير ما يكون في طرف غالب وتفنى شرطة الموت،\n\"فإذا كان يوم الرابع ، نهَد إليهم بقية أهل الإسلام فيجعل الله الدَّبرة عليهم، \nفيُقتلون مقتلةً لا يُرى مثلها، أو لم يُرَ مثلها حتى إن الطائر ليمر بجنَبَاتهم، فما يَخلُفهم حتى يَخِر ميتاً\"\nيعني أخبار القتال بين جيش الروم وجيش المسلمين هتكون انتشرت في كل مكان،\nففي اليوم الرابع هيقوم بقية أهل الإسلام ويلتحقوا بالجيش المسلم لقتال جيش الروم،\nوهتحصل مقتلة كبيرة جدا في جيش الروم النصارى لدرجة إن الجثث هتبقى مالية الأرض والجثث هتبقى مُنتنة،\nوهتخلي الهواء في الجو مُنتن لدرجة إن لو طائر عدّى من المكان هيقع ميت من الرائحة المنتنة الموجودة بسبب فساد الهواء إللي فوق الجثث الميتة،\nوبعد المعركة يبدأ الناس يشوفوا مين الباقي من أهلهم فيلاقوا إن من عيلة واحدة كانوا مائة مش باقي منهم غير رجل واحد ، فهنا محدش هيفرح بغنيمة ولا هيبقى في قسمة للميراث،\nودي من علامات الساعة الصغرى قال رسول الله ﷺ:\n\" إن الساعة لا تقوم حتى لا يُقَسم ميراث ولا يُفرح بغنيمة\"\nكده انتصر المسلمون على جيش الروم في معركة مرج دابق، بعدها هيتوجهوا لأقوى مدينة للنصارى قريبة من المكان إللي هم فيه وهي مدينة القسطنطينية\n☆قبل ما نعرف إيه حكاية القسطنطينية في نقطة محتاجة توضيح، \nاحنا كمسلمين في ديننا الإسلام معروف اسم المعركة إللي هتحصل بين المسلمين وبين جيش الروم النصارى في آخر الزمان باسم الملحمة الكبرى أو معركة 《مرج دابق》، أو 《الأعماق》\nالمعركة دي ماسمهاش:《هَرْمَجِدّون》\nالكلمة دي ملهاش أي وجود في ديننا لا اسماً ، ولا وُقوعاً ، لا في أحاديث صحيحة ، ولا ضعيفة \nالكلمة دي أصلها كلمة عبرية ومعناها : تل مَجِدّو أو مجيدو، ومجدو دي مدينة في فلسطين،\nفالكلمة دي موجودة عند اليهود في التوراة المُحرفة والنصارى أخذوها منهم،\nفأي معلومات عن معركة هرمجدون هي من كتب اليهود والنصارى ملناش دعوة بيهم لأن المعركة إللي في ديننا مختلفة تماما عن معركة هرمجدون دي،\nفمينفعش حد ييجي يقول إن الملحمة الكبرى أو معركة مرج دابق هي نفسها هرمجدون بتاعة اليهود والنصارى أو يسميها بنفس الاسم\nوخصوصا إن :\n◇أولا:\n الملحمة الكبرى وصفها ومكانها ثابت من رسول الله ﷺ الذي لا ينطق عن الهوى،\nأما  هرمجدون هو مجرد اسم للمكان إللي اليهود والنصارى بيدَّعو إن المعركة هتحصل فيه، ومحدش يعرف هل فعلا المعركة دي حقيقية وثابتة ولّا لأ \n◇ثانيا:\nالملحمة الكبرى هتكون بين المسلمين أتباع محمد ﷺ وبين النصارى الضالين وربنا هينصر فيها المسلمين،\nفي حين يدَّعي أهل الكتاب إن الطرفين المقاتلين في معركة \"هرمجدون\" هما :\nقوى الخير إللي بيمثلها النصارى\nوقوى الشر إللي بيمثلها المسلمين وكل من يُحَالفهم من الوثنيين، ولفظ الوثنيين عندهم يدخل فيه: \nالصينيون ، والكوريون ، والفيتناميون ، واليابانيون،\nوإللي التوراة بتسميهم : \" يأجوج ومأجوج\"\nيعني حاجة مختلفة تماما عن الملحمة الكبرى إللي أخبر عنها رسول الله ﷺ، فنصدق مين بقى؟\nرسول الله ﷺ الذي لا ينطق عن الهوى ولّا كلام اليهود والنصارى\n《الكلام بالتفصيل عن هرمجدون من موقع الإسلام سؤال وجواب\n هتلاقوا الرابط في التعليقات 》\nنرجع بقى لقصة فتح القسطنطينية، القسطنطينية كانت اسمها في القديم مدينة بيزنطة،\nولما مَلَك قُسطنطين الأكبر مَلِك الروم بنى عليها سور وسماها قسطنطينية وخلاها عاصمة مُلكه، \nوهي حاليا العاصمة التركية اسطنبول، ومدينة اسطنبول على شكل مثلث جزئين منها في البحر وجزء منها في البر،\nرسول الله ﷺ بشر إن القسطنيطية هتُفتح قبل روما،\nوفعلا تم فتح مدينة القسطنطينية على يد محمد الفاتح، لكن الفتح ده كان بالقتال واستخدام المدافع،\nومعنى كلمة فتح هي إن المدينة تكون تحت حكم المسلمين يحكموا فيها بشريعة الإسلام،\nلكن دلوقتي القسطنيطنية أو اسطنبول حاليا دولة علمانية لا يُحكم فيها بشرع الله، \nخرجت من أيدي المسلمين من ساعة ما أعلنت حكومتهم هناك أنها غير إسلامية وغير دينية وعاهدت الكفار أعداء الإسلام وحكمت أمتها بأحكام القوانين الوثنية الكافرة، وهييجي يوم ويستولي عليها النصارى وبعد معركة مرج دابق أو الملحمة الكبرى هيتوجه المسلمون لفتح القسطنيطنية مرة ثانية فتح إسلامي،\nلكن المرة دي مش هيفتحوها بالقتال، هيفتحوها بالتكبير والتهليل،\nيعني هيقعدوا يكبروا ويهللوا لحد ما تسقط المدينة وتكون في أيدي المسلمين ويحكموها بشرع الله،\nأول ما يوصلوا هيقولوا لا إله إلا الله والله أكبر ويفضلوا يهللوا ويكبروا لحد ما هيستسلم أول جزء منها إللي على البحر،\nويهللوا يكبروا للمرة الثانية فيستسلم الجزء الثاني إللي في ناحية البحر،\nويهللوا ويكبروا للمرة الثالثة فيُفرج لهم فيدخلوا المدينة،\nوهيكون في الجيش إللي هيفتح القسطنيطنية سبعون ألف من بني إسحاق، يعني سبعون ألف من الروم المسلمين،\nقال رسول الله ﷺ:\nسمعتم بمدينة جانب منها في البر وجانب منها في البحر؟ قالوا: نعم يا رسول الله،\nقال: لا تقوم الساعة حتى يغزوها سبعون ألفاً من بني إسحاق، فإذا جاؤوها نزلوا فلم يقاتلوا بسلاح ولم يرموا بسهم،\n قالوا: لا إله إلا الله والله أكبر فيسقط أحد جانبيها الذي في البحر، ثم يقولون الثانية: لا إله إلا الله والله أكبر، فيسقط جانبها الآخر،\nثم يقولوا الثالثة: لا إله إلا الله والله أكبر، فيفرج لهم، فيدخلوها فيغنموا\"\n☆ملحوظة\nفي ناس بتقول إن الفتح الثاني للقسطنيطنية ده حصل بعد فشل الانقلاب الأخير في تركيا لأن الناس خرجوا بيهللوا ويكبروا،\nطبعا الكلام ده غلط؛ لأن فتح القسطنطينية هيكون بعد الملحمة الكبرى في آخر الزمان واحنا مش في آخر الزمان، \nده غير إن تركيا لحد دلوقتي دولة علمانية لا تحكم بشرع الله، ففين بقى الفتح\nفمش أي حد يقول أي حاجة نصدقه وخصوصا إننا في زمن قلّ فيه العلم وكَثُر فيه الجهل وكله بقى يتكلم،\nفخدوا بالكم عشان متاخدوش معلومة غلط\nالمهم بقى بعد ما خلاص تم الفتح والمسلمين قاعدين بيقسموا الغنائم ومعلقين سيوفهم على أشجار الزيتون، فجأة سمعوا حد بيصرخ وبيقول:\n\"إن المسيح قد خَلفَكم في أهلِيكم \"\nيعني الحقوا المسيح الدجال خرج خلاص وهو دلوقتي في أهلكم وهيفتنهم،\nإللي صرخ ده كان الشيطان، صرخ في المسلمين صرخة كاذبة بخروج الدجال عشان يخوّفهم ويفزعهم،\nوالدجال مكنش لسه خرج، فهيترك المسلمون الغنائم وكل شيء في أيديهم ويرجعوا لأهلهم عشان خايفين عليهم من فتنة الدجال لأنها أعظم فتنة هتمر على البشرية زي ما هنشوف،\nفهيبعث قائد المسلمين ساعتها إللي هو المهدي عشرة فرسان يستطلعوا الأخبار ويتأكدوا من صحة خبر خروج الدجال،\nوالعشر فوارس دول هم خير فوارس الأرض ساعتها، زي ما قال عنهم رسول الله ﷺ:\n\" إِنِّي لَأَعْرِفُ أَسْمَاءَهُمْ وَأَسْمَاءَ آبَائِهِمْ وَأَلْوَانَ خُيُولِهِمْ هُمْ خَيْرُ فَوَارِسَ عَلَى ظَهْرِ الْأَرْضِ يَوْمَئِذٍ أَوْ مِنْ خَيْرِ فَوَارِسَ عَلَى ظَهْرِ الْأَرْضِ يَوْمَئِذٍ\"\nفبعد ما الجيش يرجع للشام هيخرج الدجال فعلا ساعتها.\n☆قبل ما نعرف مين هو الدجال عندنا سؤال:\nالمفروض إن المهدي هيكون عارف أحاديث رسول الله ﷺ وإن الدجال لسه مخرجش ليه بقى هيرجعوا ويبعتوا العشرة فوارس عشان يتأكدوا\nمن الممكن إن المهدي أو المسلمين إللي معاه موصلهمش الأحاديث إللي بتتكلم عن صرخة الشيطان،\nأو ممكن إنه فعلا وصلته الأحاديث ولكنه نسيها وده وارد،\nاحنا نفسنا بنعرف أحاديث رسول الله ﷺ وبننساها، \nده غير كده إللي ربنا قدره لازم يحصل بأي طريقة،\nيعني مادام ربنا قدّر إن الشيطان هيصيح في المسلمين وإنهم هينخدعوا بكده فأكيد هيحصل لا محالة\nإيه بقى قصة المسيح الدجال ده\nالمسيح الدجال هو رجل من بني آدم ربنا هيعطيه معجزات عشان يفتن بها بني آدم أو خلينا نقول يختبر بها بني آدم،\nوأعظم فتنة واختبار هيمر على بني آدم هي فتنة المسيح الدجال، حتى إن رسول الله ﷺ قال:\n\"ما بين خلق آدم إلى قيام الساعة أمر أكبر من الدجال\"\nوفي حديث تاني رسول الله ﷺ قال للصحابة إنه مش خايف عليهم غير من الدجال،\nوقال لهم لو الدجال خرج ورسول الله ﷺ لسه موجود فهو إللي هيتولى إقامة الحجة على الدجال وإظهار باطله،\nأما لو هو مش موجود فكل واحد مسؤول عن إقامة الحجة بنفسه، ودفع شر الدجال عن نفسه بنفسه، وربنا هيحفظ ويعين كل مسلم على الفتنة دي،\nقال رسول الله ﷺ:\n\"غيرَ الدجال أخوَفني عليكم، إن يخرج وأنا فيكم فأنا حجِيجُه دونكم، وإن يخرج ولست فيكم، فامرؤٌ حجيج نفسه، والله خليفتي على كل مسلم\"\nوكلمة المسيح بتُطلق على الصدِّيق وعلى الكذاب إللي بيضل الناس،\nيعني المسيح عيسى ابن مريم الصدّيق ، مسيح الهُدى ، يُبرِئ الأكمه والأبرص ، ويُحيِ الموتى بإذن الله،\nأما المسيح الدجال هو الكذاب إللي بيضل الناس ، مسيح الضلالة يفتن الناس بالآيات والخوارق إللي ربنا أعطاها له، زي إنزال المطر وإحياء الأرض بالنبات وغيرهما من الخوارق زي ما هنشوف بعدين،\nوالمسيح الدجال سماه رسول مسيح لأن له عين ممسوحة،\nقال رسول الله ﷺ : \" الدَّجَّالُ مَمْسُوحُ الْعَيْنِ\"\n☆ملحوظة مهمة:\nمفيش حاجة اسمها 《المسيخ》 الدجال، اللفظ الصحيح هو المسيح مش المسيخ، بعض الرواة عشان يعظموا عيسى عليه السلام ويفرقوا بينه وبين الدجال وضعوا النقطة على الحاء وقالوا إنه المسيخ،\nمع إن رسول الله ﷺ وضح وقال :\n\"مسيحُ الضلالة\" \nقال الحافظ ابن حجر : \"من قرأه بالخاء المعجمة فقد صَحّف\" يعني إللي يقول المسيخ يبقى قرأ الكلمة على غير صحتها.\nفمحدش يقول المسيخ الدجال، لكن نقول المسيح الدجال زي ما رسول الله ﷺ قال اسمه في الحديث\nومعنى كلمة الدجال هو المُمَوِّه الكذاب يعني إللي بيُكثِر من الكذب والتلبيس،\nولفظ 《الدجال》بقت عَلم على المسيح الأعور الكذاب،  والدجال اتسمى كده لأنه يغطي على الناس كُفْرَه بكذبه وتمويهه وتلبيسه عليهم،\nولأن فتنة المسيح الدجال خطيرة وهي أعظم فتنة هتمر على البشرية فمفيش نبي من الأنبياء إلا وحذر قومه من الدجال،\nقال رسول الله ﷺ:\n\"ما من نبي إلا أنذر قومه الدجال\"\nولأن أمة الإسلام هي آخر الأمم وهي إللي هيظهر فيها الدجال ربنا وضح لنا صفاته إللي بتميزه عن غيره عن طريق رسول الله ﷺ،\nعشان الناس تعرفه ويحذروا من شره ومحدش ينخدع ولا يُفتن به، وقال لنا إزاي نحمي نفسنا منه، فاللي هيتبعه بعد كل ده هيبقى جاهل سبقت عليه الشِّقوة\n◇طيب إيه هي صفاته إللي رسول الله ﷺ قال عليها\nهو رجل شاب قصير وجهه أحمر، أَفْحَج يعني يمشي مشية معيبة، وفيه عرج بسبب إن في تباعد ما بين ساقيه، \nعارفين إللي عنده تقوس في الساقين بيمشي إزاي، أهه تقريبا زي كده\nشعره مُجعد كثيف، يعني زي ما بنقول شعره أَكرت وثقيل،\nوأقرع من مقدمة الرأس وصدره عريض، وعينه اليمنى ممسوحة وهي مش غائرة داخلة لجوة كده لكنها  منتفخة وبارزة كأنها عنبة طافية،\nأما عينه اليسرى عليها ظَفرة غليظة يعني عليها جلدة غليظة تنبت عند حدقة العين يعني عينيه الاثنين معيبتان وفيهم عَور،\n ومكتوب بين عينيه \" ك ف ر \" بالحروف المقطعة ، أو\n \"كافر\" بدون تقطيع ، يقدر يقرأها كل مؤمن سواء بيعرف القراءة أو ميعرفش، \nولا يقرأها الكافر حتى لو كان بيعرف يقرأ، لأن ربنا يجعل المؤمن يرى بعين بصيرته، فيخلق الله للمؤمن الإدراك من غير ما يتعلم ، ودي حاجة طبيعية في الزمن ده لأنه زمن تنخرق فيه العادات،\nومن صفات الدجال إنه عقيم لا يُولد له، وهو ضخم وحجمه كبير،\nوالصفات دي موجودة كلها في الأحاديث الصحيحة لرسول الله ﷺ، من الأحاديث دي قال رسول الله ﷺ:\n\"إِنِّي قَدْ حَدَّثْتُكُمْ عَنْ الدَّجَّالِ حَتَّى خَشِيتُ أَنْ لا تَعْقِلُوا ، إِنَّ مَسِيحَ الدَّجَّالِ رَجُلٌ قَصِيرٌ أَفْحَجُ جَعْدٌ أَعْوَرُ مَطْمُوسُ الْعَيْنِ لَيْسَ بِنَاتِئَةٍ وَلا حَجْرَاءَ\"\nده كان وصف الدجال، سؤال بقى هل المسيح الدجال موجود دلوقتي ولّا لسه متولدش أصلا\nهنعرف الإجابة في الجزء الجاي إن شاء الله"}]);
